// ── SLA status-page config (avoids triple-escaped onclick string) ──
window._fpExportCampaigns = function() {
  const rows = (window._fpCampaignsState && window._fpCampaignsState.data && window._fpCampaignsState.data.campaigns && window._fpCampaignsState.data.campaigns.rows) ||
               (window.FP_DATA && window.FP_DATA.ga4 && window.FP_DATA.ga4.campaigns && window.FP_DATA.ga4.campaigns.rows) || [];
  if (!rows.length) {
    showToast && showToast('info', fpT('Connectez Google Analytics pour exporter les données'));
    return;
  }
  const hdr = 'Source/Medium,Sessions,Utilisateurs,Conversions,Taux conv.';
  const csvRows = rows.map(function(r) {
    var src  = (r.dimensionValues && r.dimensionValues[0] && r.dimensionValues[0].value) || '';
    var sess = (r.metricValues && r.metricValues[0] && r.metricValues[0].value) || 0;
    var usr  = (r.metricValues && r.metricValues[1] && r.metricValues[1].value) || 0;
    var conv = (r.metricValues && r.metricValues[2] && r.metricValues[2].value) || 0;
    var cr   = sess > 0 ? (conv / sess * 100).toFixed(2) + '%' : '0%';
    // Use double quotes only where field contains comma — avoid " inside onclick attr
    return [src.indexOf(',') >= 0 ? '"' + src.replace(/"/g,'""') + '"' : src, sess, usr, conv, cr].join(',');
  });
  var a = document.createElement('a');
  a.href = 'data:text/csv;charset=utf-8,' + encodeURIComponent(hdr + '\n' + csvRows.join('\n'));
  a.download = 'campagnes-' + new Date().toISOString().slice(0, 10) + '.csv';
  a.click();
  try { if (typeof window.fpTrackUsage === 'function') window.fpTrackUsage('export'); } catch(_) {}
  showToast && showToast('success', 'CSV exporté — ' + rows.length + ' campagne' + (rows.length > 1 ? 's' : ''));
};

window._fpSlaViewPage = function() {
  var u = (STATE.settings && STATE.settings.statusPageUrl) || '';
  var sp = (STATE.settings && STATE.settings.statusPage) || {};
  var spTitle = sp.title || '';
  var spDesc  = sp.description || '';
  var spMonIds = sp.monitorIds || [];
  var panelTitle = u ? 'Modifier la page de statut' : 'Configurer la page de statut';
  var btnLabel = u ? 'Enregistrer les modifications' : 'Activer la page statut';
  var monOptions = (STATE.monitors || []).map(function(m) {
    var chk = spMonIds.length === 0 || spMonIds.indexOf(m.id) >= 0;
    return '<label style="display:flex;align-items:center;gap:8px;font-size:12px;padding:4px 0;cursor:pointer">' +
      '<input type="checkbox" class="sp-mon-chk" data-mid="' + escHtml(m.id) + '" ' + (chk ? 'checked' : '') + '/>' +
      escHtml(m.name || m.url || 'Monitor') + '</label>';
  }).join('');
  openFloatPanel(panelTitle,
    '<div style="padding:4px">' +
    '<div class="fp-form-group"><label class="fp-form-label">' + fpT('Titre de la page statut') + '</label>' +
    '<input class="fp-input" id="sp-title-input" placeholder="' + fpT('Statut de nos services') + '" value="' + escHtml(spTitle) + '"/></div>' +
    '<div class="fp-form-group"><label class="fp-form-label">Description</label>' +
    '<input class="fp-input" id="sp-desc-input" placeholder="Disponibilit\u00e9 en temps r\u00e9el" value="' + escHtml(spDesc) + '"/></div>' +
    '<div class="fp-form-group"><label class="fp-form-label">' + fpT('URL publique de la page statut') + '</label>' +
    '<input class="fp-input" id="status-page-url-input" placeholder="https://status.monsite.fr" value="' + escHtml(u || '') + '"/></div>' +
    (monOptions ? '<div class="fp-form-group"><label class="fp-form-label">Monitors affich\u00e9s</label>' +
    '<div style="max-height:140px;overflow-y:auto;padding:4px;background:var(--fp-inner-card);border-radius:8px;border:1px solid var(--fp-border)">' + monOptions + '</div></div>' : '') +
    '<button class="fp-btn fp-btn-primary" id="status-page-save-btn" style="width:100%;margin-top:10px">' + btnLabel + '</button>' +
    (u ? '<div style="display:flex;gap:8px;margin-top:8px">' +
      '<button class="fp-btn fp-btn-ghost fp-btn-sm" id="status-page-open-btn" style="flex:1">Ouvrir \u2197</button>' +
      '<button class="fp-btn fp-btn-ghost fp-btn-sm" id="status-page-clear-btn" style="flex:1;color:#ef4444">' + fpT('Supprimer') + '</button>' +
    '</div>' : '') +
    '</div>'
  );
  setTimeout(function() {
    var saveBtn = document.getElementById('status-page-save-btn');
    if (!saveBtn) return;
    saveBtn.addEventListener('click', async function() {
      var newUrl  = (document.getElementById('status-page-url-input') && document.getElementById('status-page-url-input').value.trim()) || '';
      var newTitle = (document.getElementById('sp-title-input') && document.getElementById('sp-title-input').value.trim()) || '';
      var newDesc  = (document.getElementById('sp-desc-input') && document.getElementById('sp-desc-input').value.trim()) || '';
      var checkedMids = Array.from(document.querySelectorAll('.sp-mon-chk:checked')).map(function(el) { return el.dataset.mid; });
      // Validate BEFORE any state mutation or localStorage write.
      if (newUrl) {
        try {
          var _p = new URL(newUrl);
          if (_p.protocol !== 'https:' && _p.protocol !== 'http:') { showToast('warning', fpT('URL invalide — seules https:// et http:// sont accept\u00e9es')); return; }
        } catch(_ue) { showToast('warning', fpT('URL invalide — format attendu\u00a0: https://status.monsite.fr')); return; }
      }
      // Only update state + canonical localStorage once URL is confirmed valid.
      STATE.settings = STATE.settings || {};
      STATE.settings.statusPageUrl = newUrl;
      STATE.settings.statusPage = Object.assign({}, STATE.settings.statusPage || {}, {
        title: newTitle, description: newDesc, monitorIds: checkedMids
      });
      // Write to namespaced key — same as used at init and in save handler.
      fpTenantWrite('fp:settings', JSON.stringify(STATE.settings));
      try {
        // statusPageUrl only at top-level — server strips it from settings{} before JSONB merge
        // and validates protocol before accepting. settings{} contains only statusPage metadata.
        await apiAction('PATCH', '/api/me/prefs', {
          statusPageUrl: newUrl,
          settings: { statusPage: STATE.settings.statusPage }
        });
        showToast('success', newUrl ? 'Page statut enregistr\u00e9e' : 'Configuration sauvegard\u00e9e');
      } catch(_) { showToast('warning', fpT('Sauvegard\u00e9 localement — synchronisation \u00e9chou\u00e9e (r\u00e9essayez en ligne)')); }
      closeFloatPanel();
      render();
    });
    var openBtn = document.getElementById('status-page-open-btn');
    if (openBtn && u) openBtn.addEventListener('click', function() {
      // Guard: only open absolute https/http URLs (prevent javascript: XSS via stored value)
      try { var _op = new URL(u); if (_op.protocol !== 'https:' && _op.protocol !== 'http:') { showToast('warning', fpT('URL non sécurisée — impossible d\u2019ouvrir')); return; } } catch(_) { showToast('warning', fpT('URL invalide')); return; }
      window.open(u, '_blank', 'noopener,noreferrer');
    });
    var clearBtn = document.getElementById('status-page-clear-btn');
    if (clearBtn) clearBtn.addEventListener('click', async function() {
      STATE.settings = STATE.settings || {};
      STATE.settings.statusPageUrl = '';
      // Write to namespaced key — same as used at init and in save handler.
      fpTenantWrite('fp:settings', JSON.stringify(STATE.settings));
      // statusPageUrl top-level only; server strips nested field before JSONB merge.
      try { await apiAction('PATCH', '/api/me/prefs', { statusPageUrl: '' }); } catch(_) {}
      showToast('success', fpT('Page statut supprim\u00e9e'));
      closeFloatPanel();
      render();
    });
  }, 50);
};

// ── Quick mission creator — used by inline buttons throughout the dashboard ──
window._fpMQ = async function(title, category, priority, navAfter) {
  if (!title) return;
  // Anti-double-fire guard: ignore if called twice within 600ms (button double-click / event bubbling)
  var _now = Date.now();
  if (window._fpMQLastCall && _now - window._fpMQLastCall < 600) return;
  window._fpMQLastCall = _now;
  if (!STATE.missions) STATE.missions = [];
  const dup = STATE.missions.find(function(m) {
    return m.title.toLowerCase().trim() === title.toLowerCase().trim() && m.status !== 'done';
  });
  if (dup) {
    // Silently open the existing mission without an annoying warning toast
    setTimeout(function() { navigate('missions'); }, 300);
    return;
  }
  const ms = {
    id: 'qm_' + Date.now() + '_' + Math.random().toString(36).slice(2,6),
    title: title,
    category: category || 'Optimisation',
    priority: priority || 'medium',
    status: 'todo',
    createdAt: new Date().toISOString(),
    steps: [],
  };
  STATE.missions.unshift(ms);
  try {
    if (window.FP_MISSIONS_API && typeof FP_MISSIONS_API.create === 'function') {
      const saved = await FP_MISSIONS_API.create(ms);
      if (saved && saved.id) ms.id = saved.id;
    }
  } catch(e) {}
  saveMissions();
  showToast('success', 'Mission créée · ' + title.slice(0, 40));
  addLocalNotification('mission', fpT('🚀 Mission créée'), title.slice(0, 55));
  logActivityEvent('success', 'Mission créée : ' + title.slice(0, 60));
  if (navAfter) setTimeout(function() { navigate('missions'); }, 600);
};
function logActivityEvent(type, label, metadata = {}) {
  fetch('/api/activity', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ type, label, metadata }) }).catch(() => {});
}
function saveCalendarEvents() { /* calendar events persisted via API only */ }
function saveSettings() {
  fpTenantWrite('fp:settings', JSON.stringify(STATE.settings));
  apiAction('PATCH', '/api/me/prefs', { settings: STATE.settings }).catch(() => {});
}
function saveChecklist() {
  var _payload = { items: STATE.checklist, extra: STATE.checklistExtra || {} };
  apiAction('PUT', '/api/overview/checklist', _payload)
    .then(function(r) {
      if (r && r.ok) {
        showToast('success', fpT('Votre checklist est sauvegardée.'));
      } else {
        showToast('error', fpT('Impossible de sauvegarder la checklist. Nouvelle tentative au prochain changement.'));
      }
    })
    .catch(function() {
      showToast('error', fpT('Impossible de sauvegarder la checklist. Nouvelle tentative au prochain changement.'));
    });
}
function saveChecklistExtra() {
  var _payload = { items: STATE.checklist, extra: STATE.checklistExtra || {} };
  apiAction('PUT', '/api/overview/checklist', _payload)
    .then(function(r) {
      if (r && r.ok) {
        showToast('success', fpT('Votre checklist est sauvegardée.'));
      } else {
        showToast('error', fpT('Impossible de sauvegarder la checklist. Nouvelle tentative au prochain changement.'));
      }
    })
    .catch(function() {
      showToast('error', fpT('Impossible de sauvegarder la checklist. Nouvelle tentative au prochain changement.'));
    });
}
function saveNotifs() { /* notifications persisted via API only */ }

