function openCmdPalette() {
  STATE.cmdOpen = true;
  STATE.cmdQuery = '';
  STATE.cmdSel = 0;
  renderCmdPalette();
  const el = $('#fp-cmd-palette');
  el.removeAttribute('hidden');
  el.setAttribute('aria-expanded', 'true');
  setTimeout(() => $('#fp-cmd-palette .fp-cmd-input')?.focus(), 30);
  // Track search history
  if ($('#fp-search-trigger')) $('#fp-search-trigger').setAttribute('aria-expanded','true');
}

function closeCmdPalette() {
  STATE.cmdOpen = false;
  const el = $('#fp-cmd-palette');
  el.setAttribute('hidden', '');
  el.setAttribute('aria-expanded', 'false');
}

function fuzzyMatch(text, pattern) {
  const t = text.toLowerCase();
  const p = pattern.toLowerCase();
  let pi = 0;
  for (let ti = 0; ti < t.length && pi < p.length; ti++) {
    if (t[ti] === p[pi]) pi++;
  }
  return pi === p.length;
}

// ── Palette: search index restricted to pages actually in the sidebar menu ──
// Routes present in the sidebar nav (dashboard.html .fp-nav-item data-route) + AI.
const MENU_ROUTES = new Set([
  'overview','growth','missions','audits','monitors','local-seo',
  'performance','core-web-vitals','technical-audit',
  'analytics','traffic','funnels','audience','campaigns','live',
  'competitor','conversion','data-explorer',
  'reports','alerts-center','activity-feed','team','client-mode',
  'billing','settings','ai',
]);
let _cmdIndexCache = null;
function _cmdBuildIndex() {
  if (_cmdIndexCache) return _cmdIndexCache;
  // 1. Static items — keep only entries whose route is in the sidebar menu
  const base = CMD_ITEMS.filter(i => !i.route || MENU_ROUTES.has(i.route));
  // 2. Sub-pages: generate one entry per sub-nav tab of each menu page
  const subs = [];
  try {
    if (typeof SUB_NAVS !== 'undefined' && typeof PAGE_NAMES !== 'undefined') {
      MENU_ROUTES.forEach(route => {
        const tabs = SUB_NAVS[route];
        if (!Array.isArray(tabs)) return;
        tabs.forEach(t => {
          if (!t || !t.id) return;
          const pageName = PAGE_NAMES[route] || route;
          subs.push({ cat: 'Sous-pages', label: pageName + ' — ' + t.label, icon: 'activity', route, sub: t.id, shortcut: '' });
        });
      });
    }
  } catch(_) {}
  _cmdIndexCache = [...base, ...subs];
  return _cmdIndexCache;
}

// ── Palette: compute matched items from current query ──────────────────────
function _cmdComputeItems() {
  const q = STATE.cmdQuery.toLowerCase().trim();

  // CMD_ITEMS: match label OR category OR aliases
  const filtered = _cmdBuildIndex().filter(i => {
    if (!q) return true;
    const haystack = (i.label + ' ' + i.cat + ' ' + (i.aliases || '')).toLowerCase();
    return haystack.includes(q) || fuzzyMatch(i.label, q);
  });

  if (q.length < 2) return filtered.slice(0, 12);

  // Dynamic entity matches
  const auditMatches = (STATE.audits || []).filter(a =>
    (a.url||'').toLowerCase().includes(q) || (a.label||'').toLowerCase().includes(q)
  ).slice(0, 4).map(a => ({
    cat: 'Audits', label: a.url || a.label, icon: 'search', shortcut: '',
    fn: () => { navigate('audits'); setTimeout(() => { const audit = STATE.audits.find(x=>x.id===a.id); if(audit) openFloatPanel(fpT("Détail de l'audit"), renderAuditDetailPanel(audit)); },300); }
  }));

  const monitorMatches = (STATE.monitors || []).filter(m =>
    (m.name||'').toLowerCase().includes(q) || (m.url||'').toLowerCase().includes(q)
  ).slice(0, 3).map(m => ({
    cat: 'Monitors', label: m.name + ' — ' + m.url, icon: 'activity', shortcut: '',
    fn: () => { navigate('monitors'); setTimeout(() => openMonitorPanel(m), 300); }
  }));

  const missionMatches = (STATE.missions || []).filter(m =>
    (m.title||'').toLowerCase().includes(q)
  ).slice(0, 3).map(m => ({
    cat: 'Missions', label: m.title, icon: 'rocket', route: 'missions', shortcut: ''
  }));

  const reportMatches = (STATE.reports || []).filter(r =>
    (r.name||'').toLowerCase().includes(q) || (r.url||'').toLowerCase().includes(q)
  ).slice(0, 3).map(r => ({
    cat: 'Rapports', label: r.name || r.id, icon: 'file', route: 'reports', shortcut: ''
  }));

  const kwMatches = (STATE.keywords || []).filter(k =>
    (k.keyword||k.kw||'').toLowerCase().includes(q)
  ).slice(0, 3).map(k => ({
    cat: 'Mots-clés', label: k.keyword || k.kw, icon: 'search', route: 'keywords', shortcut: ''
  }));

  const competitorMatches = (STATE.competitors || []).filter(c =>
    (c.domain||c.name||'').toLowerCase().includes(q)
  ).slice(0, 3).map(c => ({
    cat: 'Concurrents', label: c.domain || c.name, icon: 'trending-up', route: 'competitor', shortcut: ''
  }));

  const alertRuleMatches = (STATE.alertRules || []).filter(r =>
    (r.name||'').toLowerCase().includes(q) || (r.type||'').toLowerCase().includes(q)
  ).slice(0, 3).map(r => ({
    cat: 'Alertes', label: r.name || r.type, icon: 'alert', route: 'alerts-center', shortcut: ''
  }));

  const calendarMatches = (STATE.calendarEvents || []).filter(e =>
    (e.title||e.name||'').toLowerCase().includes(q) || (e.url||'').toLowerCase().includes(q)
  ).slice(0, 3).map(e => ({
    cat: 'Calendrier', label: e.title || e.name || e.url, icon: 'activity', route: 'missions', shortcut: ''
  }));

  return [...filtered, ...auditMatches, ...monitorMatches, ...missionMatches, ...reportMatches, ...kwMatches, ...competitorMatches, ...alertRuleMatches, ...calendarMatches];
}

// ── Palette: render only the results pane (input untouched) ────────────────
function _cmdRenderResults() {
  const el = $('#fp-cmd-palette');
  const resultsEl = el?.querySelector('.fp-cmd-results');
  if (!resultsEl) return;

  const allItems = _cmdComputeItems();
  window._cmdCurrentItems = allItems;
  STATE.cmdSel = Math.max(0, Math.min(STATE.cmdSel, allItems.length - 1));

  if (STATE.cmdQuery.length > 2) {
    STATE.searchHistory = [STATE.cmdQuery, ...STATE.searchHistory.filter(h => h !== STATE.cmdQuery)].slice(0, 5);
    localStorage.setItem('fp:search-hist', JSON.stringify(STATE.searchHistory));
  }

  const cats = [...new Set(allItems.map(i => i.cat))];
  let html = '';

  if (allItems.length === 0 && STATE.cmdQuery.length > 0) {
    html = `<div class="fp-cmd-empty">Aucun résultat pour « ${escHtml(STATE.cmdQuery)} »</div>`;
  } else if (allItems.length === 0) {
    // Show history hints when empty query
    html = STATE.searchHistory.length
      ? `<div class="fp-cmd-category">${fpT('Récents')}</div>` + STATE.searchHistory.map((h,i) => `<div class="fp-cmd-item" data-idx="${i}"><div class="fp-cmd-item-icon">${svgIcon('search')}</div><span class="fp-cmd-item-label">${escHtml(h)}</span></div>`).join('') +
        `<div class="fp-cmd-category">Suggestions</div>` +
        ['Améliorer mon score SEO moyen','Que faire en priorité ?','Analyser les monitors DOWN','Créer un rapport mensuel','Opportunités Local SEO','Plan d\'action 30 jours']
          .map((s,i) => `<div class="fp-cmd-item" data-idx="${STATE.searchHistory.length+i}"><div class="fp-cmd-item-icon">${svgIcon('zap')}</div><span class="fp-cmd-item-label">${escHtml(s)}</span><span style="font-size:10px;color:var(--fp-text-faint);flex-shrink:0">IA</span></div>`).join('')
      : `<div class="fp-cmd-category">Suggestions rapides</div>` +
        ['Améliorer mon score SEO moyen','Que faire en priorité ?','Analyser les monitors DOWN','Créer un rapport mensuel','Opportunités Local SEO','Plan d\'action 30 jours','Voir les alertes actives','Rapport exécutif du mois']
          .map((s,i) => `<div class="fp-cmd-item" data-idx="${i}"><div class="fp-cmd-item-icon">${svgIcon('zap')}</div><span class="fp-cmd-item-label">${escHtml(s)}</span><span style="font-size:10px;color:var(--fp-text-faint);flex-shrink:0">IA</span></div>`).join('') +
        `<div class="fp-cmd-category">Navigation rapide</div>` +
        [['Audits SEO','audits'],['Monitors','monitors'],['Local SEO','local-seo'],['Assistant IA','ai'],['Rapports','reports'],['Concurrents','competitor']]
          .map(([l,r],i) => `<div class="fp-cmd-item" data-idx="${8+i}"><div class="fp-cmd-item-icon">${svgIcon('activity')}</div><span class="fp-cmd-item-label">${escHtml(l)}</span></div>`).join('');
  } else {
    let gIdx = 0;
    cats.forEach(cat => {
      html += `<div class="fp-cmd-category">${cat}</div>`;
      allItems.filter(i => i.cat === cat).forEach(item => {
        const sel = gIdx === STATE.cmdSel;
        html += `<div class="fp-cmd-item${sel ? ' selected' : ''}" data-idx="${gIdx}">
          <div class="fp-cmd-item-icon">${svgIcon(item.icon || 'search')}</div>
          <span class="fp-cmd-item-label">${highlightMatch(item.label, STATE.cmdQuery)}</span>
          ${item.shortcut ? `<kbd class="fp-cmd-item-shortcut">${item.shortcut}</kbd>` : ''}
        </div>`;
        gIdx++;
      });
    });
  }

  resultsEl.innerHTML = html;

  // Bind click + hover on result rows only
  const allItems2 = window._cmdCurrentItems;
  resultsEl.querySelectorAll('.fp-cmd-item').forEach((row, i) => {
    row.addEventListener('mouseenter', () => {
      resultsEl.querySelectorAll('.fp-cmd-item').forEach(it => it.classList.remove('selected'));
      row.classList.add('selected');
      STATE.cmdSel = i;
    });
    row.addEventListener('click', () => execCmdItem(allItems2[i]));
  });
}

function renderCmdPalette() {
  const el = $('#fp-cmd-palette');

  // Build the shell once (input + empty results container)
  el.innerHTML = `<div class="fp-cmd-box">
    <div class="fp-cmd-input-wrap">
      ${svgIcon('search')}
      <input class="fp-cmd-input" type="text" placeholder="${fpT('Rechercher une section, page, audit…')}" autocomplete="off" spellcheck="false"/>
      <kbd class="fp-cmd-esc">Esc</kbd>
    </div>
    <div class="fp-cmd-results"></div>
  </div>`;

  // Populate results immediately
  _cmdRenderResults();

  // Wire input ONCE — update STATE, refresh only results pane
  const input = el.querySelector('.fp-cmd-input');
  input.value = STATE.cmdQuery;
  input.focus();
  // Place cursor at end
  const len = input.value.length;
  input.setSelectionRange(len, len);

  input.addEventListener('input', e => {
    STATE.cmdQuery = e.target.value;
    STATE.cmdSel = 0;
    _cmdRenderResults();
  });
  input.addEventListener('keydown', e => {
    const items = window._cmdCurrentItems || [];
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      STATE.cmdSel = Math.min(STATE.cmdSel + 1, items.length - 1);
      // Just toggle CSS class — no re-render
      const rows = el.querySelectorAll('.fp-cmd-item');
      rows.forEach((r, i) => r.classList.toggle('selected', i === STATE.cmdSel));
      rows[STATE.cmdSel]?.scrollIntoView({ block: 'nearest' });
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      STATE.cmdSel = Math.max(STATE.cmdSel - 1, 0);
      const rows = el.querySelectorAll('.fp-cmd-item');
      rows.forEach((r, i) => r.classList.toggle('selected', i === STATE.cmdSel));
      rows[STATE.cmdSel]?.scrollIntoView({ block: 'nearest' });
    } else if (e.key === 'Enter') {
      const item = items[STATE.cmdSel];
      if (item) execCmdItem(item);
    } else if (e.key === 'Escape') {
      closeCmdPalette();
    }
  });
  el.addEventListener('click', e => { if (e.target === el) closeCmdPalette(); });
}

function highlightMatch(text, q) {
  if (!q) return escHtml(text);
  const idx = text.toLowerCase().indexOf(q.toLowerCase());
  if (idx < 0) return escHtml(text);
  return escHtml(text.slice(0, idx)) + `<mark style="background:rgba(37,99,235,0.3);border-radius:2px;color:#fff">${escHtml(text.slice(idx, idx + q.length))}</mark>` + escHtml(text.slice(idx + q.length));
}

function execCmdItem(item) {
  if (item.fn) { item.fn(); }
  else if (item.route) { navigate(item.route, item.sub || null); }
  closeCmdPalette();
}

// ─────────────────────────────────────────────────────────────────
// CONTEXT MENU
// ─────────────────────────────────────────────────────────────────
function showCtxMenu(e, items) {
  e.preventDefault();
  const el = $('#fp-ctx-menu');
  const x = Math.min(e.clientX, window.innerWidth - 210);
  const y = Math.min(e.clientY, window.innerHeight - (items.length * 44 + 20));

  el.innerHTML = items.map(item => {
    if (item.divider) return '<div class="fp-ctx-divider"></div>';
    return `<button class="fp-ctx-item${item.danger ? ' danger' : ''}" data-action="${item.key}">
      ${svgIcon(item.icon || 'more-h')}${item.label}
    </button>`;
  }).join('');

  el.style.left = x + 'px';
  el.style.top = y + 'px';
  el.removeAttribute('hidden');

  items.forEach(item => {
    if (item.divider) return;
    const btn = el.querySelector(`[data-action="${item.key}"]`);
    if (btn) btn.addEventListener('click', () => { item.action(); closeCtxMenu(); });
  });
}

function closeCtxMenu() { $('#fp-ctx-menu').setAttribute('hidden', ''); }

// ─────────────────────────────────────────────────────────────────
// FLOATING PANEL (Floating Sidebar)
// ─────────────────────────────────────────────────────────────────
function openFloatPanel(title, content) {
  const wrapper = $('#fp-float-panel');
  const panelTitle = $('#fp-float-panel-title');
  const body = $('#fp-float-panel-body');
  panelTitle.textContent = title;
  body.innerHTML = content;
  wrapper.removeAttribute('hidden');
  if (window.fpApplyTranslations) window.fpApplyTranslations();
  // ── Invite panel: attach handler exactly once, right here, after innerHTML ──
  if (title === 'Inviter un membre') {
    const sendBtn = body.querySelector('#invite-send');
    if (sendBtn) {
      const attachId = (globalThis.crypto && crypto.randomUUID)
        ? crypto.randomUUID()
        : Math.random().toString(36).slice(2);
      console.debug('[team-invite] handler attached', { attachId });
      sendBtn.onclick = async () => {
        console.debug('[team-invite] click received', { attachId, submitting: sendBtn.dataset.submitting });
        if (sendBtn.dataset.submitting === '1') {
          console.debug('[team-invite] duplicate click blocked', { attachId });
          return;
        }
        const email = (body.querySelector('#invite-email')?.value || '').trim();
        const role  = (body.querySelector('#invite-role')?.value  || 'viewer').toLowerCase();
        if (!email) { showToast('warning', fpT('Entrez un email')); return; }
        const maskedEmail = email.slice(0, 2) + '***@' + (email.split('@')[1] || '?');
        sendBtn.dataset.submitting = '1';
        sendBtn.disabled = true;
        sendBtn.textContent = 'Envoi\u2026';
        let resp;
        try {
          console.debug('[team-invite] POST start', { attachId, email: maskedEmail, role });
          resp = await fetch('/api/team/invite', _fpSessionFetchOptions({
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ email, role }),
          }));
          console.debug('[team-invite] POST end', { attachId, status: resp.status });
          const data = await resp.json().catch(() => ({}));
          if (resp.status === 201 && data.ok) {
            closeFloatPanel && closeFloatPanel();
            showToast('success', 'Invitation envoy\u00e9e \u00e0 ' + escHtml(email) + ' !');
            const t = await fetch('/api/team', _fpSessionFetchOptions()).then(r => r.ok ? r.json() : null).catch(() => null);
            if (t) { STATE.team = normArr(t,'members') || []; STATE.pendingInvitations = t.pendingInvitations||[]; STATE.seatUsage = t.seatUsage||null; render(); }
          } else if (resp.status === 409) {
            showToast('warning', fpT('Une invitation est d\u00e9j\u00e0 en attente pour cette adresse.'));
          } else if (resp.status === 402) {
            showToast('warning', data.error || 'Limite de sièges atteinte pour ce plan.');
          } else if (resp.status === 502) {
            showToast('warning', fpT('L\'invitation a \u00e9t\u00e9 cr\u00e9\u00e9e, mais l\'e-mail n\'a pas pu \u00eatre envoy\u00e9.'));
            closeFloatPanel && closeFloatPanel();
            const t = await fetch('/api/team', _fpSessionFetchOptions()).then(r => r.ok ? r.json() : null).catch(() => null);
            if (t) { STATE.team = normArr(t,'members') || []; STATE.pendingInvitations = t.pendingInvitations||[]; STATE.seatUsage = t.seatUsage||null; render(); }
          } else {
            showToast('error', data.error || 'Erreur lors de l\'invitation');
          }
        } catch (_e) {
          showToast('error', fpT('Erreur r\u00e9seau \u2014 r\u00e9essayez'));
        } finally {
          delete sendBtn.dataset.submitting;
          sendBtn.disabled = false;
          sendBtn.textContent = 'Envoyer l\'invitation';
        }
      };
    }
  }
}

function closeFloatPanel() { $('#fp-float-panel').setAttribute('hidden', ''); }

function openNewThreadPanel() {
  const html = '<div class="fp-form-group"><label class="fp-form-label">Client</label><input class="fp-input" id="thread-client" placeholder="Nom du client"/></div>'
    + '<div class="fp-form-group"><label class="fp-form-label">Sujet</label><input class="fp-input" id="thread-subject" placeholder="Rapport, Questions\u2026"/></div>'
    + '<div class="fp-form-group"><label class="fp-form-label">' + fpT('Type de canal') + '</label><select class="fp-input" id="thread-type"><option value="public">Public</option><option value="private">' + fpT('Privé') + '</option></select></div>'
    + '<button class="fp-btn fp-btn-primary" style="width:100%;margin-top:8px" onclick="const c=document.getElementById(\'thread-client\')?.value?.trim(),s=document.getElementById(\'thread-subject\')?.value?.trim();if(!c||!s){showToast(\'warning\',\'Remplissez tous les champs\');return;}showToast(\'success\',\'Fil créé avec \'+c+\' !\');closeFloatPanel();">' + fpT('Créer le fil') + '</button>';
  openFloatPanel('Nouveau fil de discussion', html);
}

function openNewChannelPanel() {
  const html = '<div class="fp-form-group"><label class="fp-form-label">' + fpT('Nom du canal') + '</label><input class="fp-input" id="channel-name" placeholder="' + fpT('ex: stratégie, client-martin') + '"/></div>'
    + '<div class="fp-form-group"><label class="fp-form-label">' + fpT('Visibilité') + '</label><select class="fp-input" id="channel-type"><option value="public">' + fpT("Public — toute l'équipe") + '</option><option value="private">' + fpT("Privé — sur invitation") + '</option></select></div>'
    + '<div class="fp-form-group"><label class="fp-form-label">Membres (optionnel)</label><input class="fp-input" id="channel-members" placeholder="sophie@agence.fr, mael@agence.fr"/></div>'
    + '<button class="fp-btn fp-btn-primary" id="create-channel-btn" style="width:100%;margin-top:8px">' + fpT('Créer le canal') + '</button>';
  openFloatPanel('Nouveau canal', html);
  // bind after DOM insertion
  setTimeout(() => {
    document.getElementById('create-channel-btn')?.addEventListener('click', async () => {
      const rawName = document.getElementById('channel-name')?.value?.trim() || '';
      if (!rawName) { showToast('warning', fpT('Nommez le canal')); return; }
      // Normalize: strip leading #, lowercase
      const name = rawName.replace(/^#+/, '').toLowerCase().replace(/\s+/g, '-');
      const type = document.getElementById('channel-type')?.value || 'public';
      const btn = document.getElementById('create-channel-btn');
      if (btn) { btn.disabled = true; btn.textContent = 'Création…'; }
      try {
        const r = await apiAction('POST', '/api/team/channels', { name, type }).catch(() => null);
        if (r && (r.ok || r.id || r.name)) {
          showToast('success', 'Canal #' + name + ' créé !');
          // Ensure channelMessages has an entry for the new channel
          if (!STATE.channelMessages) STATE.channelMessages = {general:[],seo:[],rapports:[],support:[]};
          if (!STATE.channelMessages[name]) STATE.channelMessages[name] = [];
          // Add to STATE.channels list (create if missing)
          if (!STATE.channels) STATE.channels = ['general','seo','rapports','support'];
          if (!STATE.channels.includes(name)) STATE.channels.push(name);
          // Switch to the new channel
          STATE.msgChannel = name;
          closeFloatPanel();
          // Re-fetch channel list from server (backend persists channels)
          const fresh = await fetch('/api/team/channels', _fpSessionFetchOptions()).then(r2 => r2.ok ? r2.json() : null).catch(() => null);
          if (fresh) {
            const list = Array.isArray(fresh) ? fresh : (fresh.channels || []);
            list.forEach(ch => {
              const cname = (ch.name || ch).replace(/^#+/, '').toLowerCase();
              if (cname && !STATE.channels.includes(cname)) STATE.channels.push(cname);
              if (!STATE.channelMessages[cname]) STATE.channelMessages[cname] = [];
            });
          }
          render();
        } else {
          // Backend may not have this endpoint yet — add locally and continue
          if (!STATE.channelMessages) STATE.channelMessages = {general:[],seo:[],rapports:[],support:[]};
          if (!STATE.channelMessages[name]) STATE.channelMessages[name] = [];
          if (!STATE.channels) STATE.channels = ['general','seo','rapports','support'];
          if (!STATE.channels.includes(name)) STATE.channels.push(name);
          STATE.msgChannel = name;
          showToast('success', 'Canal #' + name + ' créé !');
          closeFloatPanel();
          render();
        }
      } catch(e) {
        showToast('error', fpT('Erreur lors de la création du canal'));
        if (btn) { btn.disabled = false; btn.textContent = fpT('Créer le canal'); }
      }
    });
  }, 50);
}
window.openNewChannelPanel = openNewChannelPanel;
window.openAssignTaskModal = openAssignTaskModal;

