    const _rotShuffle = (seed, arr) => {
      const a = [...arr]; let s = (seed * 1664525 + 1013904223) | 0;
      for (let i = a.length - 1; i > 0; i--) { s = (s * 1664525 + 1013904223) | 0; const j = Math.abs(s) % (i + 1); [a[i], a[j]] = [a[j], a[i]]; }
      return a;
    };
