  window.fpConfirmDeleteAccount = async function() {
    const _inp = document.getElementById('fp-delete-confirm-input');
    // Use trimmed comparison — silent return was the original bug vector.
    // Show an explicit hint instead of silently no-op'ing.
    if (!_inp || _inp.value.trim() !== 'SUPPRIMER') {
      const _hint = document.getElementById('fp-delete-confirm-hint');
      if (_hint) { _hint.textContent = 'Tapez SUPPRIMER en majuscules pour confirmer.'; }
      if (_inp)  { _inp.style.borderColor = '#ef4444'; _inp.focus(); }
      return;
    }
    document.getElementById('fp-delete-account-modal')?.remove();
    showToast('info', fpT('Suppression du compte en cours…'));
      try {
        const r = await apiAction('DELETE', '/api/billing/account');
        if (r && r.ok) {
          // Clear local auth state IMMEDIATELY. Deferring it to the redirect timer
          // let an in-flight 401 bounce the tab to signin.html first, leaving the
          // dead session token behind in sessionStorage.
          try { document.cookie.split(';').forEach(c => { document.cookie = c.split('=')[0].trim() + '=;expires=Thu, 01 Jan 1970 00:00:00 GMT;path=/'; }); } catch(e) {}
          try { localStorage.clear(); sessionStorage.clear(); } catch(e) {}
          showToast('success', fpT('Compte supprimé. Redirection…'));
          if (document.visibilityState === 'visible' && performance.now() > 2000) {
            setTimeout(() => { window.location.href = '/signin.html'; }, 400);
          } else {
            setTimeout(() => { window.location.href = '/signin.html'; }, 1800);
          }
        } else if (r && r.stripeCleared) {
          // Stripe subscription was cancelled but DB deletion partially failed.
          try { document.cookie.split(';').forEach(c => { document.cookie = c.split('=')[0].trim() + '=;expires=Thu, 01 Jan 1970 00:00:00 GMT;path=/'; }); } catch(e) {}
          try { localStorage.clear(); sessionStorage.clear(); } catch(e) {}
          showToast('info', fpT('Abonnement résilié. Contactez le support pour finaliser la suppression.'));
          setTimeout(() => { window.location.href = '/signin.html?deleted=1'; }, 2500);
        } else { showToast('error', (r && r.error) || 'Erreur lors de la suppression du compte'); }
      } catch(e) {
        if (e && e.name === 'AbortError') {
          // preKillSessions fired and killed the session ~3s into the 60s DELETE.
          // The browser aborted the in-flight fetch on redirect — treat as success.
          try { document.cookie.split(';').forEach(c => { document.cookie = c.split('=')[0].trim() + '=;expires=Thu, 01 Jan 1970 00:00:00 GMT;path=/'; }); } catch(_) {}
          try { localStorage.clear(); sessionStorage.clear(); } catch(_) {}
          showToast('success', fpT('Compte supprimé. Redirection…'));
          setTimeout(() => { window.location.href = '/signin.html'; }, 400);
        } else {
          showToast('error', 'Erreur : ' + ((e && e.message) || 'suppression impossible'));
        }
      }
  };

