  window._regenerateApiKey = async function(keyId, btn) {
    if (btn.dataset.pending === '1') return;
    btn.dataset.pending = '1';
    const orig = btn.textContent;
    btn.textContent = '…';
    try {
      const r = await apiAction('POST', '/api/settings/api-keys/regenerate', { type: keyId === 'pub' ? 'public' : 'secret' });
      if (r && r.key) {
        const span = document.querySelector('[data-apikey-val="' + keyId + '"]');
        if (span) span.textContent = r.key;
        // Update STATE so re-render keeps the key
        if (!STATE.settings) STATE.settings = {};
        if (keyId === 'pub') { STATE.settings.publicApiKey = r.key; STATE.settings.publicApiKeyCreatedAt = r.createdAt || new Date().toISOString(); }
        else                 { STATE.settings.secretApiKey = r.key; STATE.settings.secretApiKeyCreatedAt = r.createdAt || new Date().toISOString(); }
        // Refresh the "Créée le" date on the visible card
        try {
          const card = document.querySelector('[data-apikey-card="' + keyId + '"]');
          const dateEl = card && card.querySelector('div[style*="margin-top:6px"]');
          if (dateEl) dateEl.textContent = fpT('Cr\u00e9\u00e9e le') + ' ' + new Date().toLocaleDateString(getLocale());
        } catch(e) {}
        showToast('success', fpT('Clé régénérée ! Copiez-la maintenant.'));
        navigator.clipboard?.writeText(r.key).catch(() => {});
      } else { showToast('error', r?.error || 'Erreur régénération'); }
    } catch(e) { showToast('error', fpT('Erreur réseau')); }
    btn.textContent = orig;
    btn.dataset.pending = '0';
  };

  window._copyApiKey = async function(keyId, btn) {
    const span = document.querySelector('[data-apikey-val="' + keyId + '"]');
    const current = span ? span.textContent.trim() : '';
    // If the value contains bullets (masked), fetch real key first
    if (!current || current.includes('•')) {
      btn.textContent = '…';
      try {
        const r = await apiAction('GET', '/api/settings/api-keys');
        const key = keyId === 'pub' ? r?.publicKey : r?.secretKey;
        if (key) {
          if (span) span.textContent = key;
          if (!STATE.settings) STATE.settings = {};
          if (keyId === 'pub') STATE.settings.publicApiKey  = key;
          else                 STATE.settings.secretApiKey  = key;
          await navigator.clipboard.writeText(key);
          showToast('success', fpT('Clé copiée !'));
        } else { showToast('info', keyId === 'sec' ? 'Aucune clé secrète — cliquez Régénérer' : 'Clé non disponible'); }
      } catch(e) { showToast('info', fpT('Impossible de copier automatiquement')); }
      btn.textContent = 'Copier';
    } else {
      navigator.clipboard?.writeText(current).then(() => showToast('success', fpT('Clé copiée !'))).catch(() => showToast('info', fpT('Copiez manuellement')));
    }
  };

