  window._submitAnalyzeReview = async function() {
    const author = document.getElementById('rv-author')?.value.trim() || '';
    const rating = parseInt(document.getElementById('rv-rating')?.value || '5', 10);
    const text = document.getElementById('rv-text')?.value.trim() || '';
    const lang = document.getElementById('rv-lang')?.value || 'fr';
    if (!text) { showToast('error', fpT('Texte de l\'avis requis')); return; }
    // Dedup check: prevent adding the same review twice
    const _existingReviews = window.FP_DATA?.reviewIntel?.reviews || [];
    const _isDuplicate = _existingReviews.some(rv =>
      (rv.review_text || '').trim().toLowerCase() === text.toLowerCase() &&
      (rv.author_name || '').trim().toLowerCase() === (author || '').toLowerCase()
    );
    if (_isDuplicate) { showToast('warning', fpT('Cet avis a déjà été analysé')); return; }
    showToast('info', fpT('Analyse IA en cours…'));
    const modal = document.getElementById('fp-review-modal');
    if (modal) modal.style.display = 'none';
    try {
      const r = await window.FP_REVIEW_INTEL_API.analyzeReview({ authorName: author, rating, reviewText: text, language: lang });
      if (r?.ok) {
        const a = r.analysis || {};
        // Server has saved the review to DB. Reload from API so FP_DATA.reviewIntel.reviews
        // is sourced from DB (not a local_* ephemeral entry that disappears on F5).
        try {
          const _freshData = await window.FP_REVIEW_INTEL_API.load().catch(() => null);
          if (_freshData) {
            window.FP_DATA = window.FP_DATA || {};
            window.FP_DATA.reviewIntel = _freshData;
          } else {
            // Fallback: insert optimistically so UI updates immediately if API reload fails
            if (!window.FP_DATA) window.FP_DATA = {};
            if (!window.FP_DATA.reviewIntel) window.FP_DATA.reviewIntel = { reviews: [], stats: {}, alerts: [] };
            if (!Array.isArray(window.FP_DATA.reviewIntel.reviews)) window.FP_DATA.reviewIntel.reviews = [];
            const _newRev = {
              id: r.reviewId || ('rev_' + Date.now()),
              author_name: author || 'Auteur inconnu', rating, review_text: text,
              sentiment: a.sentiment || 'neutre', score: a.score || null,
              ai_reply: a.suggestedReply || null, created_at: new Date().toISOString(),
            };
            window.FP_DATA.reviewIntel.reviews.unshift(_newRev);
            const _rvs = window.FP_DATA.reviewIntel.reviews;
            const _st  = window.FP_DATA.reviewIntel.stats || {};
            _st.totalReviews = _rvs.length;
            _st.avgRating = Math.round((_rvs.reduce((s, rv) => s + (rv.rating || 0), 0) / _rvs.length) * 10) / 10;
            _st.sentimentDist = {
              positive: _rvs.filter(rv => /posit/i.test(rv.sentiment || '')).length,
              negative: _rvs.filter(rv => /n[eé]gat/i.test(rv.sentiment || '')).length,
              neutral:  _rvs.filter(rv => !/posit|n[eé]gat/i.test(rv.sentiment || '')).length,
            };
            _st.reputationScore = Math.min(100, Math.round((_st.avgRating / 5) * 70 + (_st.sentimentDist.positive / Math.max(1, _rvs.length)) * 30));
            window.FP_DATA.reviewIntel.stats = _st;
          }
        } catch(_e) { /* non-blocking */ }
        const _isPos = /posit/i.test(a.sentiment || '');
        const _isNeg = /n[eé]gat/i.test(a.sentiment || '');
        const sentColor = _isPos ? '#22c55e' : _isNeg ? '#ef4444' : '#f59e0b';
        const renderList = (items) => (items||[]).map(it=>`<li style="font-size:12px;color:var(--fp-text-muted);margin-bottom:2px">${escHtml(it)}</li>`).join('');
        openFloatPanel(fpT('📊 Analyse IA — résultat'),
          `<div style="display:flex;flex-direction:column;gap:14px;padding:4px 0">
            <div style="display:flex;align-items:center;gap:10px;padding:12px;border-radius:10px;background:${sentColor}12;border:1px solid ${sentColor}30">
              <div style="font-size:24px">${_isPos ? '😊' : _isNeg ? '😟' : '😐'}</div>
              <div>
                <div style="font-size:14px;font-weight:700;color:${sentColor}">Sentiment : ${escHtml(a.sentiment || 'neutre')}</div>
                ${a.score != null ? `<div style="font-size:11px;color:var(--fp-text-muted)">Score : ${escHtml(String(a.score))}/10</div>` : ''}
              </div>
            </div>
            ${(a.strengths||[]).length ? `<div><div style="font-size:11px;font-weight:700;color:#22c55e;margin-bottom:6px">✅ Points forts</div><ul style="margin:0;padding-left:16px">${renderList(a.strengths)}</ul></div>` : ''}
            ${(a.weaknesses||[]).length ? `<div><div style="font-size:11px;font-weight:700;color:#ef4444;margin-bottom:6px">⚠ Points faibles</div><ul style="margin:0;padding-left:16px">${renderList(a.weaknesses)}</ul></div>` : ''}
            ${(a.tips||[]).length ? `<div><div style="font-size:11px;font-weight:700;color:#2563EB;margin-bottom:6px">💡 Conseils</div><ul style="margin:0;padding-left:16px">${renderList(a.tips)}</ul></div>` : ''}
            ${a.suggestedReply ? `<div style="padding:12px;border-radius:10px;background:var(--fp-inner-card);border:1px solid var(--fp-border)"><div style="font-size:11px;font-weight:700;color:var(--fp-text-soft);margin-bottom:6px">💬 Réponse suggérée</div><div style="font-size:12px;color:var(--fp-text-muted);line-height:1.5">${escHtml(a.suggestedReply)}</div></div>` : ''}
          </div>`
        );
        await window.FP_REVIEW_INTEL_API.load();
        render(STATE.currentSection);
      } else {
        const _rmsg = r?.error || r?.message || "Analyse indisponible";
        if ((r?.status === 403) || (r?.code === 'ADDON_REQUIRED')) {
          showToast('info', "Module Review Intelligence requis — activez-le depuis la page Facturation.");
        } else {
          showToast('error', _rmsg);
        }
      }
    } catch(_re) {
      const _remsg = String(_re);
      if (_remsg.includes('403') || _remsg.includes('ADDON')) {
        showToast('info', "Module Review Intelligence requis — activez-le depuis la page Facturation.");
      } else {
        showToast('error', "Erreur lors de l\'analyse : " + _remsg);
      }
    }
  };
  // ── Intégrations window functions (extracted from non-executing innerHTML script) ──
  window._intgTab = window._intgTab || 'hub';
