function renderTeamFilesSearch(q) {
  const rows = document.querySelectorAll('.team-file-row');
  const term = (q || '').toLowerCase();
  rows.forEach(r => { r.style.display = (!term || r.dataset.fileName.includes(term)) ? '' : 'none'; });
}
async function deleteTeamFile(id) {
  window.fpDarkConfirm('Supprimer ce fichier ?', async () => {
    const r = await apiAction('DELETE', `/api/team/files/${id}`).catch(() => null);
    if (r && r.ok) { showToast('success', fpT('Fichier supprimé')); STATE.teamFiles = (STATE.teamFiles||[]).filter(f=>f.id!==id); render(); }
    else showToast('error', fpT('Erreur suppression'));
  }, 'Supprimer le fichier');
}
async function downloadFileAssetById(id) {
  try {
    const res = await fetch(`/api/team/files/${id}/content`, _fpSessionFetchOptions());
    if (!res.ok) throw new Error('Not found');
    const blob = await res.blob();
    const fn = res.headers.get('content-disposition')?.match(/filename="([^"]+)"/)?.[1] || 'fichier';
    const a = Object.assign(document.createElement('a'), { href: URL.createObjectURL(blob), download: fn });
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    URL.revokeObjectURL(a.href);
    showToast('success', `${fn} téléchargé`);
  } catch(e) { showToast('error', fpT('Erreur téléchargement')); }
}

// ─────────────────────────────────────────────────────────────────
// GROWTH PAGE — Animation system
// ─────────────────────────────────────────────────────────────────
function initPageAnimations(route, sub) {
  requestAnimationFrame(() => {
    // Workspace health ring animation — draw in from full offset to target
    document.querySelectorAll('.fp-workspace-health-ring, .fp-score-ring-fill').forEach(el => {
      const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if (reduced) {
        // No animation — jump straight to the final arc so the ring is always visible.
        const t = parseFloat(el.dataset.ringTargetOffset || '0');
        if (Number.isFinite(t)) el.style.strokeDashoffset = String(t);
        return;
      }
      const targetOffset = parseFloat(el.dataset.ringTargetOffset || el.getAttribute('stroke-dashoffset') || '0');
      const circ = parseFloat(el.dataset.ringCirc || el.getAttribute('stroke-dasharray') || '238.76');
      // Start at full circle hidden, transition to target
      el.style.transition = 'none';
      el.style.strokeDashoffset = String(circ);
      el.style.opacity = '0.15';
      // Force reflow, then animate
      void el.getBoundingClientRect();
      el.style.transition = 'stroke-dashoffset 1.1s cubic-bezier(0.4,0,0.2,1), opacity 0.4s ease';
      el.style.strokeDashoffset = String(targetOffset);
      el.style.opacity = '1';
    });

    if (route !== 'growth' || sub !== null) return;
    document.querySelectorAll('[data-ring-target]').forEach(el => {
      const val = parseFloat(el.dataset.ringTarget);
      const rad = parseFloat(el.dataset.ringR || '32');
      el.style.strokeDashoffset = (2 * Math.PI * rad * (1 - val / 100)).toFixed(2);
    });
    document.querySelectorAll('[data-count-to]').forEach(el => {
      const target = parseFloat(el.dataset.countTo);
      if (!isFinite(target)) return; // P1.1: guard NaN% from null growthRing values
      const suffix = el.dataset.suffix || '';
      const prefix = el.dataset.prefix || '';
      const dec = parseInt(el.dataset.decimals || '0');
      const dur = 1400;
      const t0 = performance.now();
      const tick = now => {
        const p = Math.min(1, (now - t0) / dur);
        const ease = 1 - Math.pow(1 - p, 3);
        const v = target * ease;
        el.textContent = prefix + (dec > 0 ? v.toFixed(dec) : Math.round(v).toLocaleString(getLocale())) + suffix;
        if (p < 1) requestAnimationFrame(tick);
      };
      requestAnimationFrame(tick);
    });
  });
}

function growthRing(val, color, sz, sw, label, sub) {
  sz = sz || 84; sw = sw || 7; label = label || ''; sub = sub || '';
  const r = sz / 2 - sw - 1;
  const c = +(2 * Math.PI * r).toFixed(2);
  return '<div class="fp-growth-ring-item">' +
    '<div style="position:relative;width:' + sz + 'px;height:' + sz + 'px;flex-shrink:0">' +
      '<svg width="' + sz + '" height="' + sz + '" viewBox="0 0 ' + sz + ' ' + sz + '" style="transform:rotate(-90deg);overflow:visible;display:block">' +
        '<circle cx="' + (sz/2) + '" cy="' + (sz/2) + '" r="' + r + '" fill="none" stroke="rgba(255,255,255,0.06)" stroke-width="' + sw + '"/>' +
        '<circle cx="' + (sz/2) + '" cy="' + (sz/2) + '" r="' + r + '" fill="none" stroke="' + color + '" stroke-width="' + sw + '" stroke-dasharray="' + c + '" stroke-dashoffset="' + c + '" stroke-linecap="round" data-ring-target="' + val + '" data-ring-r="' + r + '" style="transition:stroke-dashoffset 1.6s cubic-bezier(.4,0,.2,1)"/>' +
      '</svg>' +
      '<div style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column">' +
        '<span style="font-size:' + (sz < 72 ? 11 : 13) + 'px;font-weight:800;color:#f1f5ff;font-family:var(--fp-font-head);line-height:1" data-count-to="' + val + '" data-suffix="%">0%</span>' +
      '</div>' +
    '</div>' +
    '<div style="margin-top:7px;text-align:center">' +
      '<div style="font-size:10.5px;font-weight:600;color:var(--fp-text-soft)">' + label + '</div>' +
      (sub ? '<div style="font-size:9.5px;color:' + color + ';font-weight:500;margin-top:1px">' + sub + '</div>' : '') +
    '</div>' +
  '</div>';
}

var _sparkUidCounter = 0;

// ── Growth projection helper ────────────────────────────────────────────────
// Returns {stepPerWeek, score30d, score60d, score90d, sampleSize} or null.
// Requires at least 2 valid, dated audit-history points; never returns fabricated data.
function computeGrowthProjection(auditHistory) {
  if (!Array.isArray(auditHistory) || auditHistory.length < 2) return null;
  var pts = auditHistory.map(function(h) { return Number(h.avg || h.score || 0); }).filter(function(v) { return Number.isFinite(v) && v > 0; });
  if (pts.length < 2) return null;
  var step = (pts[pts.length - 1] - pts[0]) / Math.max(1, pts.length - 1);
  var last = pts[pts.length - 1];
  return {
    stepPerWeek: step,
    score30d: Math.min(99, Math.round(last + step * 4)),
    score60d: Math.min(99, Math.round(last + step * 8)),
    score90d: Math.min(99, Math.round(last + step * 12)),
    sampleSize: pts.length,
  };
}

// Returns true only when the series has ≥2 valid numeric points.
function hasValidTimeSeries(series) {
  return Array.isArray(series) && series.length >= 2 &&
    series.every(function(v) { return typeof v === 'number' && Number.isFinite(v); });
}

// Lazy-loads data required by the Growth Command Center that is not fetched
// globally (keyword stats/opportunities + local-seo).  Fire-and-forget:
// guards prevent duplicate requests; re-renders once data arrives.
function loadGrowthData() {
  var _needKw   = !(STATE.keywordData && STATE.keywordData.stats) && !STATE._growthKwLoading;
  var _needLseo = !STATE.localSeo && !STATE._growthLseoLoading;
  if (!_needKw && !_needLseo) return;
  if (_needKw) {
    STATE._growthKwLoading = true;
    Promise.allSettled([
      apiFetch('/api/keywords/stats').then(function(r) { STATE.keywordData = STATE.keywordData || {}; STATE.keywordData.stats = r || {}; }).catch(function() {}),
      apiFetch('/api/keywords/opportunities').then(function(r) { STATE.keywordData = STATE.keywordData || {}; STATE.keywordData.opportunities = (r && r.opportunities) || []; }).catch(function() {}),
    ]).then(function() { STATE._growthKwLoading = false; if (STATE.route === 'growth') render(); });
  }
  if (_needLseo) {
    STATE._growthLseoLoading = true;
    apiFetch('/api/local-seo')
      .then(function(r) { if (r && typeof r === 'object') STATE.localSeo = r; })
      .catch(function(err) {
        // Set a sentinel so _needLseo stays false permanently — prevents retry loop on 404/error
        STATE.localSeo = { _status: err && err.message && err.message.includes('404') ? 'unavailable' : 'error' };
      })
      .finally(function() { STATE._growthLseoLoading = false; if (STATE.route === 'growth') render(); });
  }
}

function miniSparkSvg(values, color, w, h) {
  w = w || 72; h = h || 26;
  const mn = Math.min.apply(null, values), mx = Math.max.apply(null, values), rng = mx - mn || 1;
  const pts = values.map(function(v, i) {
    return (i / (values.length - 1) * w).toFixed(1) + ',' + (h - 3 - ((v - mn) / rng) * (h - 6)).toFixed(1);
  }).join(' ');
  const last = pts.split(' ').pop().split(',');
  const uid = 'sg' + (++_sparkUidCounter);
  return '<svg width="' + w + '" height="' + h + '" viewBox="0 0 ' + w + ' ' + h + '" style="display:block;flex-shrink:0">' +
    '<defs><linearGradient id="' + uid + '" x1="0" y1="0" x2="0" y2="1">' +
      '<stop offset="0%" stop-color="' + color + '" stop-opacity="0.20"/>' +
      '<stop offset="100%" stop-color="' + color + '" stop-opacity="0"/>' +
    '</linearGradient></defs>' +
    '<polygon points="' + pts + ' ' + w + ',' + h + ' 0,' + h + '" fill="url(#' + uid + ')"/>' +
    '<polyline points="' + pts + '" fill="none" stroke="' + color + '" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>' +
    '<circle cx="' + last[0] + '" cy="' + last[1] + '" r="2.5" fill="' + color + '"/>' +
  '</svg>';
}

function growthForecastSvg(past, future) {
  // P0.3: Guard against null/empty arrays — return empty SVG rather than crashing
  var _safePast   = Array.isArray(past)   ? past.filter(function(v) { return typeof v === 'number' && isFinite(v); }) : [];
  var _safeFuture = Array.isArray(future) ? future.filter(function(v) { return typeof v === 'number' && isFinite(v); }) : [];
  if (_safePast.length < 2 || _safeFuture.length < 1) {
    return '<div style="height:108px;display:flex;align-items:center;justify-content:center;color:var(--fp-text-faint);font-size:12px">Données insuffisantes pour la projection</div>';
  }
  past = _safePast; future = _safeFuture;
  var _fcDark = document.documentElement.getAttribute('data-theme') !== 'light';
  var _fcGrid = _fcDark ? 'rgba(255,255,255,.07)' : 'rgba(0,0,0,.10)';
  var _fcLabel = _fcDark ? 'rgba(148,163,184,.5)' : 'rgba(0,0,0,.45)';
  var _fcDiv = _fcDark ? 'rgba(255,255,255,.15)' : 'rgba(0,0,0,.18)';
  var _fcDivLbl = _fcDark ? 'rgba(255,255,255,.28)' : 'rgba(0,0,0,.35)';
  const all = past.concat(future);
  const mn = Math.min.apply(null, all) - 3, mx = Math.max.apply(null, all) + 3;
  const W = 540, H = 108, pL = 28, pR = 8, pT = 8, pB = 20;
  const iW = W - pL - pR, iH = H - pT - pB;
  const total = past.length + future.length - 1;
  function xy(v, i) {
    return [+(pL + (i / (total - 1)) * iW).toFixed(1), +(pT + iH - ((v - mn) / (mx - mn)) * iH).toFixed(1)];
  }
  const pastPts = past.map(function(v, i) { return xy(v, i); });
  const futurePts = future.slice(1).map(function(v, i) { return xy(v, past.length + i); });
  const allPts = pastPts.concat(futurePts);
  const divX = pastPts[pastPts.length - 1][0];
  function bezier(pts) {
    var d = 'M' + pts[0][0] + ' ' + pts[0][1];
    for (var i = 1; i < pts.length; i++) {
      var cpx = ((pts[i-1][0] + pts[i][0]) / 2).toFixed(1);
      d += ' C' + cpx + ' ' + pts[i-1][1] + ' ' + cpx + ' ' + pts[i][1] + ' ' + pts[i][0] + ' ' + pts[i][1];
    }
    return d;
  }
  const pastArea = pastPts.map(function(p) { return p[0] + ' ' + p[1]; }).join(' L ');
  const futureStart = [pastPts[pastPts.length-1]].concat(futurePts);
  const futureArea = futureStart.map(function(p) { return p[0] + ' ' + p[1]; }).join(' L ');
  const xLabels = ['J-90','J-60','J-30','Auj.','+30j','+60j','+90j'];
  const gridLines = [0.25, 0.5, 0.75, 1].map(function(s) {
    var y = (pT + iH * (1 - s)).toFixed(1);
    var val = Math.round(mn + (mx - mn) * s);
    return '<line x1="' + pL + '" y1="' + y + '" x2="' + (W-pR) + '" y2="' + y + '" stroke="' + _fcGrid + '" stroke-width="1"/>' +
      '<text x="' + (pL-3) + '" y="' + (+y+4) + '" text-anchor="end" font-size="7.5" fill="' + _fcLabel + '" font-family="Inter,sans-serif">' + val + '</text>';
  }).join('');
  const dots = allPts.filter(function(_, i) { return i % 2 === 0; }).map(function(p, ii) {
    return '<circle cx="' + p[0] + '" cy="' + p[1] + '" r="3" fill="' + (ii * 2 >= past.length ? '#22c55e' : 'var(--fp-accent)') + '"/>';
  }).join('');
  const xTicks = xLabels.map(function(l, i) {
    return '<text x="' + (pL + (i/(xLabels.length-1))*iW).toFixed(0) + '" y="' + (H-3) + '" text-anchor="middle" font-size="7.5" fill="' + _fcLabel + '" font-family="Inter,sans-serif">' + l + '</text>';
  }).join('');
  return '<svg viewBox="0 0 ' + W + ' ' + H + '" width="100%" height="' + H + '" xmlns="http://www.w3.org/2000/svg">' +
    '<defs>' +
      '<linearGradient id="fcp" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="rgba(37,99,235,.2)"/><stop offset="100%" stop-color="rgba(37,99,235,0)"/></linearGradient>' +
      '<linearGradient id="fcf" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="rgba(34,197,94,.18)"/><stop offset="100%" stop-color="rgba(34,197,94,0)"/></linearGradient>' +
    '</defs>' +
    gridLines +
    '<line x1="' + divX + '" y1="' + pT + '" x2="' + divX + '" y2="' + (H-pB) + '" stroke="' + _fcDiv + '" stroke-width="1" stroke-dasharray="4 3"/>' +
    '<text x="' + (+divX+4) + '" y="' + (pT+10) + '" font-size="7.5" fill="' + _fcDivLbl + '" font-family="Inter,sans-serif">Auj.</text>' +
    '<path d="M ' + pastArea + ' L ' + pastPts[pastPts.length-1][0] + ' ' + (H-pB) + ' L ' + pL + ' ' + (H-pB) + 'Z" fill="url(#fcp)"/>' +
    '<path d="M ' + futureArea + ' L ' + futureStart[futureStart.length-1][0] + ' ' + (H-pB) + ' L ' + divX + ' ' + (H-pB) + 'Z" fill="url(#fcf)"/>' +
    '<path d="' + bezier(futureStart) + '" fill="none" stroke="rgba(34,197,94,.7)" stroke-width="2" stroke-dasharray="7 4"/>' +
    '<path d="' + bezier(pastPts) + '" fill="none" stroke="var(--fp-accent)" stroke-width="2.5"/>' +
    dots + xTicks +
  '</svg>';
}

function radarChartSvg(dims, sz) {
  sz = sz || 168;
  const cx = sz/2, cy = sz/2, r = sz*0.34, n = dims.length;
  function ang(i) { return (i/n)*2*Math.PI - Math.PI/2; }
  function ptStr(i, v) {
    var a = ang(i);
    return (cx + r*(v/100)*Math.cos(a)).toFixed(1) + ',' + (cy + r*(v/100)*Math.sin(a)).toFixed(1);
  }
  var rings = [.25,.5,.75,1].map(function(s) {
    var pts = dims.map(function(_, i) { var a=ang(i); return (cx+r*s*Math.cos(a)).toFixed(1)+','+(cy+r*s*Math.sin(a)).toFixed(1); }).join(' ');
    return '<polygon points="' + pts + '" fill="none" stroke="rgba(255,255,255,.07)" stroke-width="1"/>';
  }).join('');
  var axes = dims.map(function(_, i) {
    var a=ang(i);
    return '<line x1="'+cx+'" y1="'+cy+'" x2="'+(cx+r*Math.cos(a)).toFixed(1)+'" y2="'+(cy+r*Math.sin(a)).toFixed(1)+'" stroke="rgba(255,255,255,.06)" stroke-width="1"/>';
  }).join('');
  var uPts = dims.map(function(d,i) { return ptStr(i,d.user); }).join(' ');
  var cPts = dims.map(function(d,i) { return ptStr(i,d.comp); }).join(' ');
  var labels = dims.map(function(d,i) {
    var a=ang(i), lx=(cx+(r+20)*Math.cos(a)).toFixed(1), ly=(cy+(r+20)*Math.sin(a)).toFixed(1);
    return '<text x="'+lx+'" y="'+ly+'" text-anchor="middle" dominant-baseline="middle" font-size="8.5" fill="rgba(200,216,248,.65)" font-family="Inter,sans-serif">'+d.label+'</text>';
  }).join('');
  return '<svg width="'+sz+'" height="'+sz+'" viewBox="0 0 '+sz+' '+sz+'" style="display:block;overflow:visible">'+rings+axes+
    '<polygon points="'+cPts+'" fill="rgba(239,68,68,.1)" stroke="rgba(239,68,68,.4)" stroke-width="1.5"/>'+
    '<polygon points="'+uPts+'" fill="rgba(37,99,235,.18)" stroke="rgba(37,99,235,.9)" stroke-width="2"/>'+
    labels+'</svg>';
}

// ─────────────────────────────────────────────────────────────────
// NEW PAGE: GROWTH DASHBOARD — Command Center v3
