// AUDIENCE API MODULE — fetch from /api/audience/*
// ══════════════════════════════════════════════════════════════════════
window._fpAudienceState = {};

window._fpAudienceAPI = {
  async loadAll(days) {
    const d = (Number.isInteger(days) && days > 0) ? days : 30;
    window._fpAudienceState = { loading: true, loaded: false, data: window._fpAudienceState.data || null, error: null };
    _fpLoadWatchdog('_fpAudienceState');
    render();
    try {
      const res = await apiFetch(`/api/audience/overview?days=${d}`);
      if (!res?.ok) throw new Error(res?.error || 'Erreur audience');
      const payload = res.data || {};
      const data = { audience: payload.audience || {}, overview: payload.overview || {}, source: 'ga4', connected: payload.connected };
      window._fpAudienceState = { loading: false, loaded: true, data, error: null };
    } catch(e) {
      window._fpAudienceState = { loading: false, loaded: true, data: window._fpAudienceState.data, error: e.message || String(e) };
    }
    render();
  },
};

// ══════════════════════════════════════════════════════════════════════
// LIVE API MODULE — fetch from /api/live/* with 30s auto-poll + cleanup
// ══════════════════════════════════════════════════════════════════════
window._fpLiveState = {};
let _fpLiveTimer = null;

window._fpLiveAPI = {
  async refresh() {
    if (window.STATE?.subRoute !== 'live') { this.stopPolling(); return; }
    window._fpLiveState = { loading: !window._fpLiveState.loaded, loaded: window._fpLiveState.loaded, data: window._fpLiveState.data || null, error: null };
    if (window._fpLiveState.loading) _fpLoadWatchdog('_fpLiveState');
    try {
      const res = await apiFetch('/api/live/realtime', { backgroundPoll: true });
      if (!res?.ok) throw new Error(res?.error || 'Erreur realtime');
      const rtData = res.realtime || { activeUsers: 0, rows: [] };
      window._fpLiveState = { loading: false, loaded: true, data: { realtime: rtData, connected: res.connected, source: 'ga4' }, error: null };
      // Update DOM elements without full re-render to preserve scroll
      const cntEl = document.getElementById('fp-live-count');
      if (cntEl) { cntEl.textContent = String(rtData.activeUsers || 0); }
      const tsEl = document.getElementById('fp-live-last-update');
      if (tsEl) { tsEl.textContent = 'Dernière MAJ : ' + new Date().toLocaleTimeString(getLocale(), {hour:'2-digit',minute:'2-digit',second:'2-digit'}); }
      if (!window._fpLiveState.loaded || cntEl === null) render();
    } catch(e) {
      window._fpLiveState = { loading: false, loaded: true, data: window._fpLiveState.data, error: e.message || String(e) };
      render();
    }
  },
  startPolling(ms) {
    const interval = (typeof ms === 'number' && ms >= 5000) ? ms : 30000;
    this.stopPolling();
    this.refresh();
    _fpLiveTimer = setInterval(() => window._fpLiveAPI.refresh(), interval);
  },
  stopPolling() {
    if (_fpLiveTimer) { clearInterval(_fpLiveTimer); _fpLiveTimer = null; }
  },
  setInterval(ms) { this.startPolling(ms); },
};

// ══════════════════════════════════════════════════════════════════════
// CONVERSION API MODULE — fetch from /api/conversion/* routes
// All data is real GA4 only — no synthetic/fake values returned.
// ══════════════════════════════════════════════════════════════════════
window._fpConversionState = {};

window._fpConversionAPI = {
  async loadAll(days) {
    const d = (Number.isInteger(days) && days > 0) ? days : 30;
    window._fpConversionState = { loading: true, loaded: false, days: d, data: window._fpConversionState.data || null, error: null };
    _fpLoadWatchdog('_fpConversionState');
    render();
    try {
      const [status, overview, events, landingPages, sources, devices, geo] = await Promise.all([
        apiFetch('/api/conversion/status').catch(() => null),
        apiFetch('/api/conversion/overview?days=' + d).catch(() => null),
        apiFetch('/api/conversion/events?days=' + d).catch(() => null),
        apiFetch('/api/conversion/landing-pages?days=' + d).catch(() => null),
        apiFetch('/api/conversion/sources?days=' + d).catch(() => null),
        apiFetch('/api/conversion/devices?days=' + d).catch(() => null),
        apiFetch('/api/conversion/geo?days=' + d).catch(() => null),
      ]);
      const statusConnected = status && typeof status.connected === 'boolean' ? status.connected : null;
      const overviewConnected = overview && typeof overview.connected === 'boolean' ? overview.connected : null;
      // A missing or malformed status response is not proof of disconnection.
      // Keep the page in a retryable state instead of showing "Connecter GA4".
      if (statusConnected === null && overviewConnected !== true) {
        window._fpConversionState = {
          loading: false,
          loaded: true,
          days: d,
          data: null,
          error: 'Statut GA4 indisponible — réessayez dans un instant.',
        };
        render();
        return;
      }
      const connected = statusConnected ?? overviewConnected;
      // Tokens-only OAuth (property discovery still running) must NOT render
      // as an empty "connected" dataset — surface the discovering state.
      const discovering = !!(status && status.discovering === true);
      const data = {
        connected,
        discovering,
        source: 'ga4',
        overview:     overview?.data      || null,
        events:       events?.data?.events || [],
        totalRevenue: events?.data?.totalRevenue || 0,
        totalConversions: events?.data?.totalConversions || 0,
        avgRevenuePerConversion: events?.data?.avgRevenuePerConversion || null,
        pages:        landingPages?.data?.pages  || [],
        sources:      sources?.data?.sources     || [],
        devices:      devices?.data?.devices     || [],
        geo:          geo?.data?.geo             || [],
      };
      window._fpConversionState = { loading: false, loaded: true, days: d, data, error: null };
    } catch(e) {
      window._fpConversionState = { loading: false, loaded: true, days: d, data: window._fpConversionState.data, error: e.message || String(e) };
    }
    render();
  },
  refresh() { return this.loadAll(window._fpConversionState.days || 30); },
};

// ── Loading / Error skeleton helpers ──────────────────────────────────────────
function _fpConvLoadingSkeleton() {
  return '<div class="fp-section-header"><div><h1>🎯 Conversion GA4</h1><div class="fp-section-sub">Chargement des données…</div></div></div>' + renderPageSkeleton({ hero: false, stats: 4, statH: 80, toolbar: false, cards: 4, cardCols: 2, cardH: 160, rows: 0 });
}
