// FP ADDONS API — Real Add-ons Marketplace client
// ═══════════════════════════════════════════════════════════════════════════════

window.FP_ADDONS_API = {
  async load() {
    try {
      const data = await apiFetch('/api/addons').catch(() => null);
      if (!data) return;
      window.FP_DATA = window.FP_DATA || {};
      window.FP_DATA.addons = {
        active:      data.addons      || {},
        orgAddons:   data.orgAddons   || [],
        definitions: data.definitions || {},
        quotas:      data.quotas      || {},
        plan:        data.plan        || 'pro',
      };
    } catch(e) { console.warn('[FP_ADDONS_API] load error:', e); }
  },

  async activate(addonKey, quantity) {
    showToast('info', `Activation de ${addonKey}…`);
    try {
      // quantity is only meaningful for quantity add-ons (packs); server clamps 1..20
      // and ignores it for flag add-ons. Body is always sent for consistency.
      const qty = Math.min(20, Math.max(1, parseInt(quantity, 10) || 1));
      const r = await apiFetch(`/api/addons/${encodeURIComponent(addonKey)}/activate`, { method: 'POST', body: JSON.stringify({ quantity: qty }) });
      if (r?.ok) {
        if (window.FP_DATA?.addons) window.FP_DATA.addons.active = r.addons || window.FP_DATA.addons.active;
        await this.load().catch(() => {});
        render();
        showToast('success', `Add-on ${addonKey} activé`);
      } else showToast('error', r?.error || 'Activation impossible');
      return r;
    } catch(e) {
      const message = e && (e.error || e.message) ? (e.error || e.message) : 'Activation impossible';
      showToast('error', String(message));
      return null;
    }
  },

  async deactivate(addonKey) {
    try {
      const r = await apiFetch(`/api/addons/${encodeURIComponent(addonKey)}/deactivate`, { method: 'POST' });
      if (r?.ok) {
        if (window.FP_DATA?.addons?.active) window.FP_DATA.addons.active[addonKey] = false;
        await this.load().catch(() => {});
        render();
        showToast('success', `Add-on ${addonKey} désactivé`);
      } else {
        showToast('error', r?.error || 'Désactivation impossible');
      }
      return r;
    } catch(e) { showToast('error', String(e)); return null; }
  },

  async buyCredits(pack) {
    // Direct Stripe Checkout — no pricing/cart detour for existing customers
    return window._fpBuyAICredits(pack);
  },
};

