// FP AI CREDITS API — Real AI Credits & Usage client
// ═══════════════════════════════════════════════════════════════════════════════

window.FP_AI_CREDITS_API = {
  async load() {
    try {
      await loadAICredits();
      const credits = STATE.aiCredits;
      if (!credits) return null;
      window.FP_DATA = window.FP_DATA || {};
      window.FP_DATA.aiCredits = {
        ...credits,
        total: Number(credits.limit) + Number(credits.extra),
        remaining: Math.max(0, Number(credits.limit) + Number(credits.extra) - Number(credits.used)),
        pct: credits.limit > 0 ? Math.round((Number(credits.used) / (Number(credits.limit) + Number(credits.extra))) * 100) : 0,
        resetAt: credits.resetDate,
      };
      return window.FP_DATA.aiCredits;
    } catch(e) { console.warn('[FP_AI_CREDITS_API] load error:', e); }
  },

  async consume(feature, metadata) {
    try {
      const result = await apiFetch('/api/ai-credits/consume', { method: 'POST', body: JSON.stringify({ feature, metadata }) });
      await loadAICredits();
      render();
      return result;
    } catch(e) { console.warn('[FP_AI_CREDITS_API] consume error:', e); return null; }
  },

  async buyCredits(pack) {
    // Direct Stripe Checkout — no pricing/cart detour for existing customers
    return window._fpBuyAICredits(pack);
  },
};

// ── Shared AI-credit purchase: Stripe Checkout redirect ───────────────────────
// Called from both FP_ADDONS_API.buyCredits and FP_AI_CREDITS_API.buyCredits.
// Uses the Stripe-hosted Checkout page (redirect) so the purchase flow is
// consistent with subscriptions. After payment the user lands on checkout-return.html
// which reads checkoutType=ai_credits from billing/verify and shows "crédits ajoutés".

// Public alias — inline onclick="fpBuyAICredits('pack')" buttons use this
window.fpBuyAICredits = function(pack) { return window._fpBuyAICredits(pack); };

// ── AI credit pack key mapping: API format → pricing/checkout addon key ──────
var _fpAiCreditPackMap = {
  'ai_credits_50k':  'aiCreditsPack50k',
  'ai_credits_200k': 'aiCreditsPack200k',
  'ai_credits_500k': 'aiCreditsPack500k',
};

window._fpBuyAICredits = function(pack) {
  // Required flow: Dashboard → Pricing (AI Token Pack selected) → Stripe Checkout → Return
  // Map API-format pack key to the addon key used by pricing.html / checkout.html
  var addonKey = _fpAiCreditPackMap[pack] || pack;
  var cart = { plan: null, addons: {}, fromDashboard: true };
  cart.addons[addonKey] = 1;
  try { localStorage.setItem('fp_cart', JSON.stringify(cart)); } catch(e) {}
  showToast('info', fpT('Ouverture de la page de paiement…'));
  // Small delay so the toast is visible before navigation
  setTimeout(function() {
    window.location.href = '/pricing.html?from=dashboard&addon=' + encodeURIComponent(addonKey);
  }, 300);
};

// ── Cumulative usage tracking for client-side exports ─────────────────────────
// Fire-and-forget; deletion of the exported item never decrements this history.
window.fpTrackUsage = async function(kind) {
  try {
    await apiFetch('/api/billing/usage-events', { method: 'POST', body: JSON.stringify({ kind }) });
  } catch(_) { return false; }
  return true;
};

// ── Auto-load all integrations on page start ──────────────────────────────────

(function _autoLoadGoogleIntegrations() {
  const doLoad = () => {
    if (typeof window === 'undefined') return;

    // Google integrations
    window.FP_GBP_API.load().then(() => { if (STATE.gbp?.connected) render(); }).catch(() => {});
    window.FP_GA4_API.load().then(() => { if (window.FP_DATA?.ga4?.connected) render(); }).catch(() => {});
    window.FP_GSC_API.load().then(() => { if (STATE.gsc?.connected) render(); }).catch(() => {});

    // SaaS engine integrations — load silently in background, re-render if data arrives
    const _reloadIfData = (key) => () => {
      const has = key === 'automation'
        ? window.FP_DATA?.automation?.workflows?.length > 0
        : window.FP_DATA?.[key] && (Array.isArray(window.FP_DATA[key]) ? window.FP_DATA[key].length > 0 : true);
      if (has) render();
    };

    window.FP_BEHAVIORAL_API.load().then(_reloadIfData('behavioral')).catch(() => {});
    window.FP_CRO_API.load().then(_reloadIfData('cro')).catch(() => {});
    window.FP_REVENUE_LEAK_API.load().then(_reloadIfData('revenueLeak')).catch(() => {});
    window.FP_FORECAST_API.load().then(_reloadIfData('forecast')).catch(() => {});
    window.FP_AUTOMATION_API.load().then(_reloadIfData('automation')).catch(() => {});
    window.FP_ADDONS_API.load().then(_reloadIfData('addons')).catch(() => {});
    window.FP_INTEGRATIONS_API.load().then(_reloadIfData('integrations')).catch(() => {});
    window.FP_CRM_API.load().then(_reloadIfData('crm')).catch(() => {});
    window.FP_MARKET_INTEL_API.load().then(_reloadIfData('marketIntel')).catch(() => {});
    window.FP_PERMISSIONS_API.load().then(_reloadIfData('permissions')).catch(() => {});
    window.FP_REVIEW_INTEL_API.load().then(_reloadIfData('reviewIntel')).catch(() => {});
    window.FP_GBP_POSTS_API.load().then(_reloadIfData('gbpPosts')).catch(() => {});
    window.FP_LOCAL_MAPS_API.load().then(_reloadIfData('localMaps')).catch(() => {});
    window.FP_SSO_API.load().then(_reloadIfData('sso')).catch(() => {});
    window.FP_AI_CREDITS_API.load().then(_reloadIfData('aiCredits')).catch(() => {});

    // Missions — load from real backend
    if (typeof window.FP_MISSIONS_API !== 'undefined') {
      window.FP_MISSIONS_API.load().then(missions => {
        // Accept any array response (including empty) — withOrgDb returning [] used to block updates.
        if (Array.isArray(missions)) {
          STATE.missions = missions;
          if (STATE.route === 'missions') render();
        }
      }).catch(() => {});
    }
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => setTimeout(doLoad, 0), { once: true });
  } else {
    setTimeout(doLoad, 0);
  }
})();


