// ═══════════════════════════════════════════════════════════════════════════════
// RENDER: CRM HUB
// ═══════════════════════════════════════════════════════════════════════════════
function renderCRM() {
  const plan = STATE.me?.plan || 'Pro';
  const isStd = plan === 'Standard';
  const isUltra = plan === 'Agency' || plan === 'Ultra';
  const crmData = window.FP_DATA?.crm || {};
  const integrations = crmData.status?.integrations || [];
  const stats = crmData.status?.stats || {};
  const logs = crmData.logs || [];
  const limit = isStd ? 1 : isUltra ? Infinity : 3;
  const connected = integrations.filter((i) => i.status === 'connected');
  const activeTab = window._crmTab || 'overview';

  const providers = [
    { id:'hubspot',    name:'HubSpot',     icon:'🎯', color:'#ff7a59', desc:'CRM marketing leader. Contacts, deals, pipelines et séquences email.' },
    { id:'salesforce', name:'Salesforce',  icon:'☁️', color:'#00a1e0', desc:'Enterprise CRM. Leads, opportunités et reporting avancé.' },
    { id:'pipedrive',  name:'Pipedrive',   icon:'🔧', color:'#00c851', desc:'CRM commercial visuel. Pipeline deals et automatisations.' },
    { id:'zoho',       name:'Zoho CRM',    icon:'🔴', color:'#e42527', desc:'Suite CRM complète. Contacts, ventes et analytics.' },
    { id:'monday',     name:'Monday CRM',  icon:'📋', color:'#ff3d57', desc:'CRM collaboratif. Gestion de projets et suivi clients.' },
    { id:'airtable',   name:'Airtable',    icon:'📊', color:'#18bfff', desc:'Base de données flexible. CRM sur-mesure en quelques clics.' },
    { id:'notion',     name:'Notion CRM',  icon:'📄', color:'#ffffff', desc:'Workspace all-in-one. Pages clients, notes et pipelines.' },
    { id:'close',      name:'Close CRM',   icon:'🔑', color:'#7b68ee', desc:'CRM conçu pour les équipes sales. Calling intégré.' },
  ];

  const syncEntities = ['contacts','leads','deals','companies'];

  return `
    <div class="fp-section-header">
      <div>
        <h1 style="display:flex;align-items:center;gap:10px">🔗 CRM Hub ${connected.length>0?`<span style="font-size:11px;font-weight:700;padding:3px 10px;border-radius:20px;background:rgba(34,197,94,0.15);border:1px solid rgba(34,197,94,0.3);color:var(--fp-success)">${connected.length} connecté${connected.length>1?'s':''}</span>`:''}</h1>
        <div class="fp-section-sub">HubSpot · Salesforce · Pipedrive · Zoho · Monday · Airtable · Notion · Close</div>
      </div>
      <button class="fp-btn fp-btn-primary fp-btn-sm" onclick="window._crmTab='overview';window.FP_CRM_API?.load().then(()=>render(STATE.currentSection))">⟳ Actualiser</button>
    </div>

    ${aiBlock(
      connected.length>0
        ? `${connected.length} CRM connecté${connected.length>1?'s':''}. Dernière sync : ${stats.totalRecords||0} contacts traités, taux de succès ${stats.totalFailed>0?Math.round((1-stats.totalFailed/Math.max(stats.totalRecords,1))*100):100}%. Recommandation : activer la sync automatique pour maintenir vos données à jour.`
        : 'Connectez votre CRM pour synchroniser automatiquement vos leads, contacts et opportunités avec FlowPoint.',
      ['Connecter HubSpot', 'Configurer la sync', 'Voir le mapping']
    )}

    <!-- STATS -->
    <div class="fp-stat-row fp-mb-20">
      ${statCard('CRM connectés', String(connected.length), `sur ${isStd?1:isUltra?'∞':3} max (${plan})`, connected.length>0?'up':'neutral')}
      ${statCard('Contacts synchronisés', String(integrations.reduce((s,i) => s+(i.synced_contacts||0),0)), 'au total', 'up')}
      ${statCard('Syncs réalisées', String(stats.totalSyncs||0), 'opérations', 'up')}
      ${statCard('Latence moy.', stats.avgDurationMs ? stats.avgDurationMs+'ms' : '—', 'par sync', 'neutral')}
    </div>

    <!-- TABS -->
    <div style="display:flex;gap:0;margin-bottom:16px;border-bottom:1px solid var(--fp-border)">
      ${[['overview','🔗 Providers'],['sync','⚡ Synchronisation'],['logs','📋 Logs']].map(([id,label]) => `
        <button onclick="window._crmTab='${id}';render(STATE.currentSection)"
          style="padding:10px 18px;border:none;border-bottom:2px solid ${activeTab===id?'var(--fp-accent)':'transparent'};background:none;color:${activeTab===id?'var(--fp-accent)':'var(--fp-text-muted)'};font-size:13px;font-weight:${activeTab===id?'700':'500'};cursor:pointer">
          ${label}
        </button>
      `).join('')}
    </div>

    ${activeTab === 'overview' ? `
      <!-- PROVIDER CARDS -->
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:12px">
        ${providers.map(p => {
          const conn = integrations.find((i) => i.provider === p.id && i.status === 'connected');
          return `
            <div style="padding:16px;border-radius:12px;border:1px solid ${conn?p.color+'44':'rgba(255,255,255,0.06)'};background:${conn?p.color+'08':'var(--fp-inner-card)'}">
              <div style="display:flex;align-items:center;gap:10px;margin-bottom:10px">
                <span style="font-size:24px">${p.icon}</span>
                <div style="flex:1">
                  <div style="font-size:14px;font-weight:700;color:var(--fp-text)">${p.name}</div>
                  ${conn ? `<span style="font-size:10px;color:var(--fp-success)">● Connecté · ${conn.synced_contacts||0} contacts</span>` : `<span style="font-size:10px;color:var(--fp-text-faint)">○ Non connecté</span>`}
                </div>
              </div>
              <div style="font-size:11px;color:var(--fp-text-muted);margin-bottom:12px;line-height:1.5">${p.desc}</div>
              ${conn ? `
                <div style="display:flex;gap:6px">
                  <button class="fp-btn fp-btn-ghost fp-btn-sm" style="flex:1;font-size:10px" onclick="window._crmTab='sync';render(STATE.currentSection)">⚡ Sync</button>
                  <button class="fp-btn fp-btn-ghost fp-btn-sm" style="font-size:10px;color:var(--fp-danger)" onclick="window.FP_CRM_API?.disconnect('${p.id}').then(()=>{window.FP_CRM_API.load();render(STATE.currentSection)})">✕</button>
                </div>
              ` : `
                <button class="fp-btn fp-btn-primary fp-btn-sm" style="width:100%;font-size:11px" onclick="window._connectCrm('${p.id}','${p.name}','${p.icon}')">+ Connecter</button>
              `}
            </div>
          `;
        }).join('')}
      </div>
    ` : activeTab === 'sync' ? `
      <div class="fp-card fp-mb-16">
        <div class="fp-card-title" style="margin-bottom:14px">⚡ Synchronisation manuelle</div>
        ${connected.length === 0 ? `<div style="text-align:center;padding:24px;color:var(--fp-text-muted);font-size:12px">Connectez un CRM d\'abord pour accéder à la synchronisation.</div>` : `
          <div style="display:flex;flex-direction:column;gap:10px">
            ${connected.map((i) => `
              <div style="display:flex;align-items:center;gap:12px;padding:12px;border-radius:10px;border:1px solid var(--fp-border);background:var(--fp-inner-card)">
                <div style="flex:1">
                  <div style="font-size:13px;font-weight:600">${escHtml(i.name)}</div>
                  <div style="font-size:10px;color:var(--fp-text-faint)">Dernière sync : ${i.last_sync_at ? new Date(i.last_sync_at).toLocaleDateString(getLocale()) : 'Jamais'} · Contacts : ${i.synced_contacts||0}</div>
                </div>
                ${syncEntities.map(ent => `
                  <button class="fp-btn fp-btn-ghost fp-btn-sm" style="font-size:10px"
                    onclick="showToast('info', fpT('Sync ${ent} en cours…'));window.FP_CRM_API?.sync('${i.provider}','${ent}').then(r=>{showToast('success',r?.created+' créés, '+r?.updated+' mis à jour');window.FP_CRM_API.load();render(STATE.currentSection)}).catch(e=>showToast('error',String(e)))">
                    ⟳ ${ent}
                  </button>
                `).join('')}
              </div>
            `).join('')}
          </div>
        `}
      </div>

      <!-- SYNC SETTINGS -->
      <div class="fp-card">
        <div class="fp-card-title" style="margin-bottom:14px">⚙️ Paramètres de synchronisation</div>
        <div style="display:flex;flex-direction:column;gap:10px">
          ${[
            {label:'Sync automatique', desc:'Synchronise toutes les 60 min', active:true},
            {label:'Sync bidirectionnelle', desc:'FlowPoint ↔ CRM en temps réel', active:false, pro:true},
            {label:'Résolution de conflits', desc:'FlowPoint a priorité sur les doublons', active:true},
            {label:'Webhook sync', desc:'Mise à jour instantanée via webhooks CRM', active:false, ultra:true},
          ].map(s => `
            <div style="display:flex;align-items:center;gap:12px;padding:10px 0;border-bottom:1px solid rgba(255,255,255,0.04)">
              <div style="flex:1">
                <div style="font-size:13px;font-weight:600;color:var(--fp-text)">${s.label}</div>
                <div style="font-size:11px;color:var(--fp-text-faint)">${s.desc}</div>
              </div>
              ${s.ultra&&!isUltra ? `<span style="font-size:10px;color:var(--fp-text-faint)">Ultra</span>` : s.pro&&isStd ? `<span style="font-size:10px;color:var(--fp-text-faint)">Pro</span>` : `<button class="fp-toggle${s.active?' on':''}" onclick="(function(btn){var key=btn.dataset.settingKey||'setting';var val=!btn.classList.contains('on');apiAction('PATCH','/api/me/prefs',{settings:{[key]:val}}).then(()=>{btn.classList.toggle('on');}).catch(()=>showToast('error', fpT('Erreur')));}).call(this,this)"></button>`}
            </div>
          `).join('')}
        </div>
      </div>
    ` : `
      <!-- LOGS -->
      <div class="fp-card">
        <div class="fp-card-title" style="margin-bottom:14px">📋 Historique de synchronisation</div>
        ${logs.length===0 ? `<div style="text-align:center;padding:24px;color:var(--fp-text-muted);font-size:12px">Aucune synchronisation encore. Lancez une sync pour commencer.</div>` : `
          <div style="overflow-x:auto">
            <table class="fp-data-table">
              <thead><tr><th>CRM</th><th>Direction</th><th>Entité</th><th style="text-align:center">Créés</th><th style="text-align:center">MàJ</th><th style="text-align:center">Échecs</th><th style="text-align:center">Durée</th><th>Statut</th><th>Date</th></tr></thead>
              <tbody>
                ${logs.map((l) => `<tr>
                  <td style="font-size:12px;font-weight:600">${escHtml(l.integration_name||l.provider||'—')}</td>
                  <td style="font-size:10px;color:var(--fp-text-faint)">${l.direction||'—'}</td>
                  <td style="font-size:11px">${l.entity_type||'—'}</td>
                  <td style="text-align:center;font-size:12px;color:var(--fp-success)">${l.records_created||0}</td>
                  <td style="text-align:center;font-size:12px">${l.records_updated||0}</td>
                  <td style="text-align:center;font-size:12px;color:${l.records_failed>0?'var(--fp-danger)':'var(--fp-text-faint)'}">${l.records_failed||0}</td>
                  <td style="text-align:center;font-size:11px;color:var(--fp-text-faint)">${l.duration_ms?l.duration_ms+'ms':'—'}</td>
                  <td><span style="font-size:10px;font-weight:700;color:${l.status==='success'?'var(--fp-success)':l.status==='failed'?'var(--fp-danger)':'var(--fp-warning)'}">${l.status||'—'}</span></td>
                  <td style="font-size:10px;color:var(--fp-text-faint)">${l.started_at?new Date(l.started_at).toLocaleDateString(getLocale(),{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}):''}</td>
                </tr>`).join('')}
              </tbody>
            </table>
          </div>
        `}
      </div>
    `}

    <!-- CONNECT MODAL -->
    <div id="fp-crm-modal" style="display:none;position:fixed;inset:0;background:rgba(0,0,0,0.75);z-index:1000;align-items:center;justify-content:center">
      <div class="fp-card" style="width:440px;max-width:92vw;padding:24px">
        <div id="fp-crm-modal-title" style="font-size:16px;font-weight:700;margin-bottom:16px">Connecter un CRM</div>
        <div style="display:flex;flex-direction:column;gap:12px">
          <div>
            <label style="font-size:11px;color:var(--fp-text-muted);display:block;margin-bottom:4px">Access Token OAuth</label>
            <input id="crm-token" class="fp-input" placeholder="eyJ..." type="password"/>
          </div>
          <div>
            <label style="font-size:11px;color:var(--fp-text-muted);display:block;margin-bottom:4px">Portal ID (optionnel)</label>
            <input id="crm-portal" class="fp-input" placeholder="12345678"/>
          </div>
          <div style="font-size:10px;color:var(--fp-text-faint);padding:8px;background:rgba(37,99,235,0.06);border-radius:8px;border:1px solid rgba(37,99,235,0.15)">
            ℹ️ En production, le flux OAuth redirige vers votre CRM pour autorisation sécurisée.
          </div>
        </div>
        <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:16px">
          <button class="fp-btn fp-btn-ghost" onclick="document.getElementById('fp-crm-modal').style.display='none'">Annuler</button>
          <button class="fp-btn fp-btn-primary" onclick="window._submitCrmConnect()">Connecter</button>
        </div>
      </div>
    </div>
    <script>
    window._crmTab = window._crmTab || 'overview';
    window._currentCrmProvider = null;
    window._connectCrm = function(id, name, icon) {
      window._currentCrmProvider = id;
      document.getElementById('fp-crm-modal-title').textContent = icon + ' Connecter ' + name;
      document.getElementById('fp-crm-modal').style.display = 'flex';
    };
    window._submitCrmConnect = async function() {
      const token = document.getElementById('crm-token').value.trim();
      const portal = document.getElementById('crm-portal').value.trim();
      if (!token) { showToast('error', fpT('Access token requis')); return; }
      showToast('info', fpT('Connexion en cours…'));
      try {
        const r = await window.FP_CRM_API.connect(window._currentCrmProvider, { accessToken: token, portalId: portal || undefined });
        if (r?.ok) {
          document.getElementById('fp-crm-modal').style.display = 'none';
          showToast('success', fpT('CRM connecté !'));
          await window.FP_CRM_API.load();
          render(STATE.currentSection);
        } else {
          const msg = r?.error || 'Erreur de connexion';
          if (msg.includes('Limite')) showToast('error', fpT('Limite du plan atteinte. Passez à un plan supérieur.'));
          else showToast('error', msg);
        }
      } catch(e) { showToast('error', String(e)); }
    };
    </script>
  `;
}

// ═══════════════════════════════════════════════════════════════════════════════
// RENDER: MARKET INTELLIGENCE
// ═══════════════════════════════════════════════════════════════════════════════
function renderMarketIntelligence() {
  const plan = STATE.me?.plan || 'Pro';
  const isUltra = plan === 'Agency' || plan === 'Ultra';
  const mi = window.FP_DATA?.marketIntel || {};
  const trends = mi.trends || [];
  const opportunities = mi.opportunities || [];
  const movements = mi.competitor_movements || [];
  const signals = mi.signals || [];
  const reports = mi.reports || [];
  const stats = mi.stats || {};
  const activeTab = window._miTab || 'overview';

  const trendDir = (dir) => dir==='up'?'<span style="color:var(--fp-success);font-size:11px">▲</span>':dir==='down'?'<span style="color:var(--fp-danger);font-size:11px">▼</span>':'<span style="color:var(--fp-text-faint);font-size:11px">→</span>';
  const diffColor = (d) => d==='low'?'var(--fp-success)':d==='high'?'var(--fp-danger)':'var(--fp-warning)';
  const sigIcon = (s) => s.severity==='critical'?'🚨':s.severity==='warning'?'⚠️':'ℹ️';

  return `
    <div class="fp-section-header">
      <div>
        <h1>🧠 Market Intelligence</h1>
        <div class="fp-section-sub">Tendances · Opportunités · Mouvements concurrents · Signaux marché</div>
      </div>
      <div class="fp-section-actions">
        <button class="fp-btn fp-btn-ghost fp-btn-sm" onclick="window.FP_MARKET_INTEL_API?.load().then(()=>render(STATE.currentSection))">⟳ Actualiser</button>
        <button class="fp-btn fp-btn-primary fp-btn-sm" onclick="showToast('info', fpT('Génération rapport IA…'));window.FP_MARKET_INTEL_API?.generateReport().then(r=>{showToast('success', fpT('Rapport généré !'));window.FP_MARKET_INTEL_API.load();render(STATE.currentSection)})">🤖 Générer rapport IA</button>
      </div>
    </div>

    ${aiBlock(
      trends.length>0
        ? `${stats.emergingTrends||0} tendance${(stats.emergingTrends||0)>1?'s':''} émergente${(stats.emergingTrends||0)>1?'s':''} détectée${(stats.emergingTrends||0)>1?'s':''}. Score opportunité moyen : <strong>${stats.avgOpportunityScore||0}/100</strong>. ${opportunities.length>0?`<strong>${opportunities.length} opportunité${opportunities.length>1?'s':''}</strong> à saisir dès maintenant.`:''}`
        : 'Analyse du marché en cours. Les tendances et opportunités seront détectées automatiquement.',
      ['Voir les opportunités', 'Analyser les concurrents', 'Générer rapport stratégique']
    )}

    <!-- STAT ROW -->
    <div class="fp-stat-row fp-mb-16">
      ${statCard('Tendances détectées', String(trends.length), `dont ${stats.emergingTrends||0} émergentes`, 'up')}
      ${statCard('Score moy. opport.', String(stats.avgOpportunityScore||0)+'/100', 'potentiel de croissance', stats.avgOpportunityScore>70?'up':'neutral')}
      ${statCard('Opportunités', String(opportunities.length), 'à exploiter maintenant', 'up')}
      ${statCard('Mouvements concurrents', String(movements.length), 'détectés ce mois', movements.length>0?'down':'up')}
      ${statCard('Signaux marché', String(signals.length), 'actifs', signals.filter(s=>s.severity==='critical').length>0?'down':'neutral')}
      ${statCard('Rapports IA', String(reports.length), 'générés', 'up')}
    </div>

    <!-- TABS -->
    <div style="display:flex;gap:0;margin-bottom:16px;border-bottom:1px solid var(--fp-border)">
      ${[['overview','🧠 Vue d\'ensemble'],['trends','📈 Tendances'],['opportunities','💎 Opportunités'],['competitors','⚔️ Concurrents'],['signals','📡 Signaux'],['reports','📋 Rapports']].map(([id,label]) => `
        <button onclick="window._miTab='${id}';render(STATE.currentSection)"
          style="padding:10px 16px;border:none;border-bottom:2px solid ${activeTab===id?'var(--fp-accent)':'transparent'};background:none;color:${activeTab===id?'var(--fp-accent)':'var(--fp-text-muted)'};font-size:12px;font-weight:${activeTab===id?'700':'500'};cursor:pointer">
          ${label}
        </button>
      `).join('')}
    </div>

    ${activeTab==='overview' ? `
      <div class="fp-grid-2 fp-mb-16">
        <!-- TOP TRENDS -->
        <div class="fp-card">
          <div class="fp-card-title" style="margin-bottom:12px">🔥 Top tendances</div>
          ${trends.slice(0,5).map((t) => `
            <div style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid rgba(255,255,255,0.04)">
              ${trendDir(t.trend_direction)}
              <div style="flex:1;min-width:0">
                <div style="font-size:12px;font-weight:600;color:var(--fp-text)">${escHtml(t.keyword)}</div>
                <div style="font-size:10px;color:var(--fp-text-faint)">${t.search_volume?.toLocaleString(getLocale())||0} req/mois · ${t.geo||'France'}</div>
              </div>
              <div style="text-align:right">
                <div style="font-size:12px;font-weight:700;color:var(--fp-success)">+${t.growth_rate}%</div>
                <div style="font-size:10px;color:var(--fp-text-faint)">${t.opportunity_score}/100</div>
              </div>
            </div>
          `).join('')}
        </div>
        <!-- TOP OPPORTUNITIES -->
        <div class="fp-card">
          <div class="fp-card-title" style="margin-bottom:12px">💎 Meilleures opportunités</div>
          ${opportunities.slice(0,4).map((o) => `
            <div style="padding:10px 0;border-bottom:1px solid rgba(255,255,255,0.04)">
              <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px;margin-bottom:4px">
                <div style="font-size:12px;font-weight:700;color:var(--fp-text)">${escHtml(o.title)}</div>
                <div style="font-size:11px;font-weight:700;color:var(--fp-accent);flex-shrink:0">${o.score}/100</div>
              </div>
              <div style="font-size:10px;color:var(--fp-text-muted);margin-bottom:6px">${escHtml(o.description||'')}</div>
              <div style="display:flex;gap:6px;align-items:center">
                <span style="font-size:9px;padding:2px 6px;border-radius:6px;background:${diffColor(o.difficulty)}22;color:${diffColor(o.difficulty)}">${o.difficulty}</span>
                <span style="font-size:9px;color:var(--fp-text-faint)">${o.timeframe||''}</span>
                ${o.estimated_traffic?`<span style="font-size:9px;color:var(--fp-success)">+${o.estimated_traffic.toLocaleString(getLocale())} visites/mois</span>`:''}
              </div>
            </div>
          `).join('')}
        </div>
      </div>
      <!-- SIGNALS -->
      <div class="fp-card">
        <div class="fp-card-title" style="margin-bottom:12px">📡 Signaux marché actifs</div>
        <div style="display:flex;flex-direction:column;gap:8px">
          ${signals.length===0 ? `<div style="text-align:center;padding:16px;color:var(--fp-text-muted);font-size:12px">Aucun signal détecté pour le moment.</div>` :
          signals.map((s) => `
            <div style="display:flex;align-items:center;gap:12px;padding:10px 12px;border-radius:10px;border:1px solid var(--fp-border);background:var(--fp-inner-card)">
              <span style="font-size:18px">${sigIcon(s)}</span>
              <div style="flex:1">
                <div style="font-size:12px;font-weight:600;color:var(--fp-text)">${escHtml(s.title)}</div>
                <div style="font-size:10px;color:var(--fp-text-muted)">${escHtml(s.description||'')}</div>
              </div>
              <span style="font-size:9px;padding:2px 8px;border-radius:8px;background:${s.severity==='critical'?'rgba(239,68,68,0.15)':s.severity==='warning'?'rgba(245,158,11,0.15)':'rgba(37,99,235,0.1)'};color:${s.severity==='critical'?'var(--fp-danger)':s.severity==='warning'?'var(--fp-warning)':'var(--fp-accent)'}">${s.severity}</span>
            </div>
          `).join('')}
        </div>
      </div>
    ` : activeTab==='trends' ? `
      <div class="fp-card">
        <div class="fp-card-title" style="margin-bottom:14px">📈 Tendances marché</div>
        <div style="overflow-x:auto">
          <table class="fp-data-table">
            <thead><tr><th>Mot-clé</th><th style="text-align:center">Direction</th><th style="text-align:center">Croissance</th><th style="text-align:center">Volume</th><th style="text-align:center">Score</th><th style="text-align:center">Compétition</th><th>Zone</th><th style="text-align:center">Émergent</th></tr></thead>
            <tbody>
              ${trends.map((t) => `<tr>
                <td style="font-size:13px;font-weight:600">${escHtml(t.keyword)}</td>
                <td style="text-align:center">${trendDir(t.trend_direction)}</td>
                <td style="text-align:center;font-size:12px;font-weight:700;color:var(--fp-success)">+${t.growth_rate}%</td>
                <td style="text-align:center;font-size:11px">${(t.search_volume||0).toLocaleString(getLocale())}</td>
                <td style="text-align:center;font-size:12px;font-weight:700;color:${t.opportunity_score>=80?'var(--fp-success)':t.opportunity_score>=60?'var(--fp-warning)':'var(--fp-text-faint)'}">${t.opportunity_score}/100</td>
                <td style="text-align:center"><span style="font-size:9px;color:${diffColor(t.competition_level)}">${t.competition_level}</span></td>
                <td style="font-size:10px;color:var(--fp-text-faint)">${t.geo||'—'}</td>
                <td style="text-align:center">${t.is_emerging?'<span style="color:var(--fp-success);font-size:11px">✓</span>':'<span style="color:var(--fp-text-faint);font-size:11px">—</span>'}</td>
              </tr>`).join('')}
            </tbody>
          </table>
        </div>
      </div>
    ` : activeTab==='opportunities' ? `
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:12px">
        ${opportunities.map((o) => `
          <div style="padding:16px;border-radius:12px;border:1px solid rgba(255,255,255,0.07);background:var(--fp-inner-card);border-top:3px solid ${o.score>=80?'var(--fp-success)':o.score>=60?'var(--fp-warning)':'var(--fp-text-faint)'}">
            <div style="display:flex;justify-content:space-between;margin-bottom:8px">
              <div style="font-size:13px;font-weight:700;color:var(--fp-text)">${escHtml(o.title)}</div>
              <div style="font-size:16px;font-weight:800;color:${o.score>=80?'var(--fp-success)':'var(--fp-accent)'}">${o.score}</div>
            </div>
            <div style="font-size:11px;color:var(--fp-text-muted);margin-bottom:10px;line-height:1.5">${escHtml(o.description||'')}</div>
            <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px">
              <span style="font-size:9px;padding:2px 8px;border-radius:8px;background:rgba(37,99,235,0.1);color:var(--fp-accent)">${o.type}</span>
              <span style="font-size:9px;padding:2px 8px;border-radius:8px;background:${diffColor(o.difficulty)}22;color:${diffColor(o.difficulty)}">${o.difficulty}</span>
              ${o.timeframe?`<span style="font-size:9px;padding:2px 8px;border-radius:8px;background:var(--fp-track);color:var(--fp-text-faint)">${o.timeframe}</span>`:''}
            </div>
            ${o.estimated_traffic?`<div style="font-size:11px;color:var(--fp-success);font-weight:600">📈 +${(o.estimated_traffic).toLocaleString(getLocale())} visites/mois estimées</div>`:''}
            <button class="fp-btn fp-btn-primary fp-btn-sm" style="width:100%;font-size:10px;margin-top:10px" onclick="_fpMQ(o.title||o.keyword||'Opportunité','Keywords','high',true)">⚡ Créer mission</button>
          </div>
        `).join('')}
      </div>
    ` : activeTab==='competitors' ? `
      <div class="fp-card">
        <div class="fp-card-title" style="margin-bottom:14px">⚔️ Mouvements concurrents</div>
        ${movements.length===0 ? `<div style="text-align:center;padding:24px;color:var(--fp-text-muted);font-size:12px">Aucun mouvement concurrent détecté. Lancez une analyse pour commencer.</div>` : movements.map((m) => `
          <div style="display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid rgba(255,255,255,0.04)">
            <div style="font-size:20px">${m.impact_level==='high'?'🚨':m.impact_level==='medium'?'⚠️':'ℹ️'}</div>
            <div style="flex:1">
              <div style="font-size:13px;font-weight:600">${escHtml(m.competitor_domain)}</div>
              <div style="font-size:11px;color:var(--fp-text-muted)">${escHtml(m.description||m.movement_type)}</div>
              ${m.keywords_gained?.length?`<div style="font-size:10px;color:var(--fp-success);margin-top:3px">+${m.keywords_gained.length} mots-clés gagnés</div>`:''}
            </div>
            <div style="text-align:right">
              <span style="font-size:9px;padding:2px 8px;border-radius:8px;background:${m.impact_level==='high'?'rgba(239,68,68,0.15)':'rgba(245,158,11,0.1)'};color:${m.impact_level==='high'?'var(--fp-danger)':'var(--fp-warning)'}">${m.impact_level}</span>
              <div style="font-size:9px;color:var(--fp-text-faint);margin-top:3px">${m.detected_at?new Date(m.detected_at).toLocaleDateString(getLocale()):''}</div>
            </div>
          </div>
        `).join('')}
      </div>
    ` : activeTab==='reports' ? `
      ${reports.length===0 ? `
        <div class="fp-card" style="text-align:center;padding:32px">
          <div style="font-size:32px;margin-bottom:12px">🤖</div>
          <div style="font-size:14px;font-weight:700;color:var(--fp-text);margin-bottom:6px">Aucun rapport généré</div>
          <div style="font-size:12px;color:var(--fp-text-muted);margin-bottom:16px">Générez votre premier rapport IA de Market Intelligence.</div>
          <button class="fp-btn fp-btn-primary" onclick="showToast('info', fpT('Génération…'));window.FP_MARKET_INTEL_API?.generateReport().then(r=>{showToast('success', fpT('Rapport prêt !'));window.FP_MARKET_INTEL_API.load();render(STATE.currentSection)})">🤖 Générer rapport IA</button>
        </div>
      ` : reports.map((r) => `
        <div class="fp-card fp-mb-12">
          <div style="display:flex;justify-content:space-between;margin-bottom:12px">
            <div style="font-size:14px;font-weight:700">${escHtml(r.title)}</div>
            <span style="font-size:10px;color:var(--fp-text-faint)">${r.generated_at?new Date(r.generated_at).toLocaleDateString(getLocale()):''}</span>
          </div>
          ${r.summary?`<div style="font-size:12px;color:var(--fp-text-muted);line-height:1.6;white-space:pre-wrap">${escHtml(r.summary)}</div>`:''}
        </div>
      `).join('')}
    ` : `<div style="padding:24px;text-align:center;color:var(--fp-text-muted)">Contenu en cours de chargement…</div>`}
  `;
}

